async function hrImportTeamV72(){if(!hrCanManage72())return;const existing=new Set(hrV72.employees.filter(e=>e.user_id).map(e=>e.user_id));const rows=teamMembers.filter(m=>m.status==='active'&&m.userId&&!existing.has(m.userId)).map((m,i)=>({workspace_id:currentWorkspaceId,user_id:m.userId,employee_no:`EMP-${String(hrV72.employees.length+i+1).padStart(4,'0')}`,full_name_ar:m.fullName||m.email||'موظف',full_name_en:m.fullName||null,email:m.email||null,status:'active',employment_type:'full_time',hire_date:new Date().toISOString().slice(0,10)}));if(!rows.length)return taskyToast(hrL72('كل أعضاء الفريق موجودون بالفعل في دليل الموظفين','All team members are already in the employee directory'),{tone:'info'});const {error}=await sb.from(hrTablesV72.employees).insert(rows);if(error)return showTaskyDialog({title:'HR',message:error.message,tone:'error'});await fetchHrDataV72(true);taskyToast(hrL72(`تم استيراد ${rows.length} موظف`,`Imported ${rows.length} employees`),{tone:'success'});}
