function hrAckPillV721(status){const s=status||'pending',labels={pending:['بانتظار الاستلام','Pending'],acknowledged:['تم الإقرار','Acknowledged'],declined:['مرفوضة','Declined'],not_required:['لا يتطلب','Not required']},x=labels[s]||[s,s];return `<span class="hr721-ack ${escapeHtml(s)}">${escapeHtml(hrL72(x[0],x[1]))}</span>`;}
function hrLeaveStageV721(r){const manager=r.manager_status||'not_required';let mCls=manager==='approved'||manager==='not_required'?'done':manager==='rejected'?'bad':'wait';let hCls=r.status==='approved'?'done':r.status==='rejected'?'bad':'wait';const managerText=manager==='not_required'?hrL72('لا يتطلب مدير','No manager approval'):manager==='approved'?hrL72('اعتماد المدير','Manager approved'):manager==='rejected'?hrL72('رفض المدير','Manager rejected'):hrL72('بانتظار المدير','Waiting for manager');const hrText=r.status==='approved'?hrL72('اعتماد HR','HR approved'):r.status==='rejected'?hrL72('مرفوض','Rejected'):r.status==='cancelled'?hrL72('ملغي','Cancelled'):hrL72('بانتظار HR','Waiting for HR');return `<div class="hr721-stage"><i class="${mCls}"></i><span>${managerText}</span><i class="${hCls}"></i><span>${hrText}</span></div>`;}

fetchHrDataV72=async function(force=false){
 if(!currentWorkspaceId)return;if(hrLoadingV72)return;if(!force&&hrLoadedWorkspaceV72===currentWorkspaceId&&!hrMigrationMissingV72)return;
 hrLoadingV72=true;hrMigrationMissingV72=false;if(activeNav==='hr')renderModule();
 try{
   const boot=await sb.rpc('tasky_hr_bootstrap_v721',{p_workspace_id:currentWorkspaceId});
   if(boot.error)throw boot.error;hrContextV72={...hrContextV72,...(boot.data||{})};
   const entries=Object.entries(hrTablesV72).filter(([k])=>k!=='employees');
   const rs=await Promise.all(entries.map(async([k,t])=>{const q=await sb.from(t).select('*').eq('workspace_id',currentWorkspaceId).limit(2000);return [k,q];}));
   for(const [k,q] of rs){if(q.error){if(/does not exist|schema cache|relation|tasky_hr_/i.test(q.error.message||''))throw q.error;console.warn('HR V72.1',k,q.error);hrV72[k]=[];}else hrV72[k]=q.data||[];}
   let employees=[];
   if(hrCanManage72()){
     const eq=await sb.from(hrTablesV72.employees).select('*').eq('workspace_id',currentWorkspaceId).limit(3000);if(eq.error)throw eq.error;employees=eq.data||[];
   }else{
     const dq=await sb.rpc('tasky_hr_directory_v721',{p_workspace_id:currentWorkspaceId});if(dq.error)throw dq.error;employees=dq.data||[];
     if(hrContextV72.employee_id){const own=await sb.from(hrTablesV72.employees).select('*').eq('id',hrContextV72.employee_id).maybeSingle();if(!own.error&&own.data){const i=employees.findIndex(e=>String(e.id)===String(own.data.id));if(i>=0)employees[i]={...employees[i],...own.data};else employees.push(own.data);}}
   }
   hrV72.employees=employees;
   hrLoadedWorkspaceV72=currentWorkspaceId;
 }catch(err){console.error('HR V72.1 load',err);hrMigrationMissingV72=/does not exist|schema cache|tasky_hr_|bootstrap_v721|directory_v721/i.test(err?.message||'');}
 finally{hrLoadingV72=false;if(activeNav==='hr')renderModule();}
};

