 if(type==='attendanceManual73'){e.preventDefault();try{const payload={employee_id:v('hr73ManualEmp'),attendance_date:v('hr73ManualDate'),shift_id:v('hr73ManualShift'),check_in:v('hr73ManualIn'),check_out:v('hr73ManualOut'),status:v('hr73ManualStatus'),notes:v('hr73ManualNotes')};const {error}=await sb.rpc('tasky_hr_save_attendance_v73',{p_workspace_id:currentWorkspaceId,p_payload:payload});if(error)throw error;closeAddModal();await fetchHrDataV72(true);taskyToast(hrL72('تم حفظ سجل الحضور وإعادة حساب الوقت','Attendance saved and time recalculated'),{tone:'success'});}catch(err){showTaskyDialog({title:'HR',message:err?.message||String(err),tone:'error'});}return;}
