Object.assign(hrTablesV72,{performanceCycles:'tasky_hr_performance_cycles',performanceGoals:'tasky_hr_performance_goals',interviews:'tasky_hr_recruitment_interviews',offers:'tasky_hr_recruitment_offers',candidateActivity:'tasky_hr_candidate_activity',skills:'tasky_hr_skills',employeeSkills:'tasky_hr_employee_skills',developmentPlans:'tasky_hr_development_plans',developmentItems:'tasky_hr_development_items'});

function hrStatusV74(s){const m={draft:['مسودة','Draft',''],open:['مفتوح','Open','ok'],calibration:['معايرة','Calibration','warn'],closed:['مغلق','Closed',''],cancelled:['ملغي','Cancelled','bad'],self_review:['تقييم ذاتي','Self review','info'],manager_review:['تقييم المدير','Manager review','warn'],completed:['مكتمل','Completed','ok'],active:['نشط','Active','ok'],applied:['تقديم','Applied','info'],screening:['فرز','Screening','info'],interview:['مقابلة','Interview','warn'],assessment:['تقييم','Assessment','warn'],offer:['عرض','Offer','ok'],hired:['تم التوظيف','Hired','ok'],rejected:['مرفوض','Rejected','bad'],withdrawn:['منسحب','Withdrawn',''],scheduled:['مجدولة','Scheduled','info'],sent:['مرسل','Sent','info'],accepted:['مقبول','Accepted','ok'],declined:['مرفوض','Declined','bad'],expired:['منتهي','Expired','bad'],enrolled:['مسجل','Enrolled','info'],attended:['حضر','Attended','warn'],failed:['لم يجتز','Failed','bad'],todo:['لم يبدأ','To do',''],doing:['قيد التنفيذ','Doing','warn'],done:['منجز','Done','ok']};const x=m[s]||[s||'—',s||'—',''];return `<span class="hr72-pill ${x[2]}">${hrL72(x[0],x[1])}</span>`;}
function hrCycleNameV74(c){return c?(lang==='ar'?(c.name_ar||c.name_en):(c.name_en||c.name_ar)):'—';}
