function hrSkillNameV74(s){return s?(lang==='ar'?(s.name_ar||s.name_en):(s.name_en||s.name_ar)):'—';}
function hrIsSelfV74(empId){return String(empId||'')===String(hrContextV72.employee_id||'');}
