function hrPctV74(v,max=100){return Math.max(0,Math.min(max,Number(v||0)));}
function hrStarsV74(v){const n=Math.max(0,Math.min(5,Math.round(Number(v||0))));return '★'.repeat(n)+'☆'.repeat(5-n);}
function hrStageLabelV74(s){const m={applied:['تقديم','Applied'],screening:['فرز','Screening'],interview:['مقابلة','Interview'],assessment:['تقييم','Assessment'],offer:['عرض','Offer'],hired:['توظيف','Hired'],rejected:['مرفوض','Rejected'],withdrawn:['منسحب','Withdrawn']};return hrL72(...(m[s]||[s,s]));}
function hrDateTimeV74(v){if(!v)return '—';try{return new Intl.DateTimeFormat(lang==='ar'?'ar-SA':'en-US',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v));}catch(_){return String(v)}}
