/* ================= V75 COMPENSATION, PAYROLL PREPARATION & GOSI ================= */
Object.assign(hrV72,{payrollSettings:hrV72.payrollSettings||[],insuranceProfiles:hrV72.insuranceProfiles||[],payrollRuns:hrV72.payrollRuns||[],payrollItems:hrV72.payrollItems||[]});
Object.assign(hrTablesV72,{payrollSettings:'tasky_hr_payroll_settings',insuranceProfiles:'tasky_hr_social_insurance_profiles',payrollRuns:'tasky_hr_payroll_runs',payrollItems:'tasky_hr_payroll_items'});
let hrPayrollMonthV75=new Date().toISOString().slice(0,7);
function hrCanPayrollV75(){return hrCanPayroll72();}
function hrPayrollRunV75(id){return hrV72.payrollRuns.find(x=>String(x.id)===String(id));}
function hrInsuranceProfileV75(empId){return hrV72.insuranceProfiles.find(x=>String(x.employee_id)===String(empId));}
function hrLatestCompV75(empId,period=null){const d=period||`${hrPayrollMonthV75}-28`;return hrV72.compensation.filter(x=>String(x.employee_id)===String(empId)&&String(x.effective_from||'')<=d).sort((a,b)=>String(b.effective_from).localeCompare(String(a.effective_from))||String(b.created_at).localeCompare(String(a.created_at)))[0]||null;}
function hrCoverageLabelV75(v){const m={unclassified:['غير مصنف','Unclassified'],saudi_legacy:['سعودي — النظام السابق','Saudi — legacy'],saudi_new_1445:['سعودي — نظام 1445 الجديد','Saudi — new 1445'],non_saudi:['غير سعودي — أخطار مهنية','Non-Saudi — occupational hazards'],gcc_manual:['خليجي — حماية ممتدة يدوية','GCC — manual extended protection'],excluded:['مستبعد/غير خاضع','Excluded / not covered']};return hrL72(...(m[v]||[v||'—',v||'—']));}
function hrPayrollStatusV75(s){const m={draft:['مسودة','Draft',''],review:['مراجعة','Review','warn'],approved:['معتمد','Approved','ok'],locked:['مقفل','Locked','info'],paid:['مدفوع','Paid','ok'],cancelled:['ملغي','Cancelled','bad']};const x=m[s]||[s,s,''];return `<span class="hr72-pill ${x[2]}">${hrL72(x[0],x[1])}</span>`;}
function hrSumV75(rows,key){return rows.reduce((s,x)=>s+Number(x[key]||0),0)}
function hrRunItemsV75(runId){return hrV72.payrollItems.filter(x=>String(x.run_id)===String(runId));}
function hrGosiRateSummaryV75(p,period){if(!p)return hrL72('يلزم تصنيف','Needs classification');const type=p.coverage_type;if(type==='saudi_legacy')return '9% + 0.75%';if(type==='saudi_new_1445'){const d=new Date(`${period||hrPayrollMonthV75}-01T00:00:00`),rate=d>=new Date('2028-07-01')?11:d>=new Date('2027-07-01')?10.5:d>=new Date('2026-07-01')?10:d>=new Date('2025-07-01')?9.5:9;return `${rate}% + 0.75%`;}if(type==='non_saudi')return hrL72('2% على صاحب العمل','2% employer');if(type==='gcc_manual')return `${Number(p.manual_employee_rate||0)}% / ${Number(p.manual_employer_rate||0)}%`;if(type==='excluded')return '0%';return hrL72('يلزم تصنيف','Needs classification');}
function hrPayrollMonthLabelV75(run){if(!run)return '—';try{return new Intl.DateTimeFormat(lang==='ar'?'ar-SA':'en-US',{month:'long',year:'numeric'}).format(new Date(`${run.period_start}T12:00:00`))}catch(_){return run.period_start}}
function hrGosiNeedsReviewV75(){return hrV72.payrollItems.some(x=>x.gosi_needs_review)}

/* V75 replaces the compensation area with a payroll workspace. */
