function hrOpenGosiCalculatorV75(empId=null,period=null){const emp=empId?hrEmp72(empId):hrV72.employees.find(e=>['active','probation','leave'].includes(e.status)),comp=emp?hrLatestCompV75(emp.id,period||`${hrPayrollMonthV75}-28`):null,empOpts=hrV72.employees.filter(e=>['active','probation','leave'].includes(e.status)).map(e=>`<option value="${e.id}" ${emp&&e.id===emp.id?'selected':''}>${escapeHtml(hrName72(e))}</option>`).join('');document.getElementById('addModalBody').innerHTML=`<div class="modal-head"><div><h3>${hrL72('حاسبة التأمينات الاجتماعية','GOSI calculator')}</h3><div style="font-size:9px;color:var(--muted)">${hrL72('حساب مباشر من ملف الموظف والفترة','Direct calculation from employee profile and period')}</div></div><button class="modal-close" onclick="closeAddModal()"><svg style="width:18px"><use href="#i-x"/></svg></button></div><form onsubmit="hrCalculateGosiV75(event)"><div class="hr72-form">${hrSelect72('hr75CalcEmp',hrL72('الموظف','Employee'),empOpts)}${hrField72('hr75CalcPeriod',hrL72('الفترة','Period'),String(period||`${hrPayrollMonthV75}-01`).slice(0,7),'month')}${hrField72('hr75CalcBasic',hrL72('الراتب الأساسي','Basic salary'),comp?.basic_salary||0,'number')}${hrField72('hr75CalcHousing',hrL72('بدل السكن','Housing allowance'),comp?.housing_allowance||0,'number')}</div><button class="submit-btn" type="submit">${hrL72('احسب الآن','Calculate now')}</button></form><div id="hr75CalcResult"></div>`;document.getElementById('addModalBody').classList.add('hr72-modal');document.getElementById('addModalOverlay').classList.remove('hidden');}
