function hrOpenSettlementFormV76(id=null){const s=id?hrSettlementV76(id):null,emp=s?hrEmp72(s.employee_id):hrV72.employees.find(e=>['active','probation','leave'].includes(e.status)),empOpts=hrV72.employees.map(e=>`<option value="${e.id}" ${emp?.id===e.id?'selected':''}>${escapeHtml(hrName72(e))}</option>`).join(''),end=s?.end_date||new Date().toISOString().slice(0,10),award=s?.award_wage??hrLatestAwardWageV76(emp?.id,end),reasons=['employer_termination','contract_expiry','mutual','resignation','retirement','death','force_majeure','article81','article80','probation','closure','activity_end','article87_full','other_manual'];document.getElementById('addModalBody').innerHTML=`<div class="modal-head"><div><h3>${id?hrL72('تعديل التسوية النهائية','Edit final settlement'):hrL72('تسوية نهائية جديدة','New final settlement')}</h3><div style="font-size:8px;color:var(--muted);margin-top:3px">${hrL72('راجع سبب الانتهاء وأجر المكافأة قبل الاعتماد.','Review termination reason and EOSB wage before approval.')}</div></div><button class="modal-close" onclick="closeAddModal()"><svg style="width:18px"><use href="#i-x"/></svg></button></div><form onsubmit="hrSubmitFormV72(event,'finalSettlement76','${id||''}')"><div class="hr72-form">${hrSelect72('hr76SetEmp',hrL72('الموظف','Employee'),empOpts)}${hrField72('hr76SetEnd',hrL72('تاريخ انتهاء العلاقة','End date'),end,'date',true)}${hrSelect72('hr76SetReason',hrL72('سبب الانتهاء','Termination reason'),reasons.map(x=>`<option value="${x}" ${s?.termination_reason===x?'selected':''}>${escapeHtml(hrSettlementReasonV76(x))}</option>`).join(''))}${hrSelect72('hr76WorkerInitiated',hrL72('من أنهى العلاقة؟','Who initiated termination?'),`<option value="false" ${!s?.worker_initiated?'selected':''}>${hrL72('صاحب العمل / انتهاء تلقائي / اتفاق','Employer / automatic / mutual')}</option><option value="true" ${s?.worker_initiated?'selected':''}>${hrL72('الموظف','Employee')}</option>`)}${hrField72('hr76AwardWage',hrL72('أجر مكافأة نهاية الخدمة','EOSB wage basis'),award,'number',true)}${hrField72('hr76LeaveDays',hrL72('أيام الإجازة غير المستخدمة','Unused leave days'),Number(s?.unused_leave_days||0),'number')}${hrField72('hr76LeaveRate',hrL72('أجر يوم الإجازة المعتمد','Confirmed leave daily wage'),Number(s?.leave_daily_rate||0),'number')}${hrField72('hr76FinalSalary',hrL72('راتب/أجر أخير مستحق','Final salary/wage due'),Number(s?.final_salary||0),'number')}${hrField72('hr76OtherEarn',hrL72('مستحقات أخرى','Other earnings'),Number(s?.other_earnings||0),'number')}${hrField72('hr76OtherDeduct',hrL72('استقطاعات/عهد أخرى','Other deductions'),Number(s?.other_deductions||0),'number')}${hrField72('hr76ManualFactor',hrL72('معامل يدوي 0–1 — للسبب الآخر','Manual factor 0–1 — other reason'),s?.termination_reason==='other_manual'?Number(s?.eos_factor||1):'','number')}<div class="field full"><label class="hr73-check"><input id="hr76ReviewConfirmed" type="checkbox" ${s?.review_override_at?'checked':''}>${hrL72('راجعت الأساس النظامي/التعاقدي وأؤكد القيم المدخلة','I reviewed the legal/contractual basis and confirm the entered values')}</label></div><div class="field full"><label>${hrL72('ملاحظات','Notes')}</label><textarea id="hr76SetNotes">${escapeHtml(s?.notes||'')}</textarea></div></div><div style="display:flex;gap:7px;flex-wrap:wrap"><button class="chip-btn" type="button" onclick="hrPreviewSettlementV76()">${hrL72('معاينة الحساب','Preview calculation')}</button><button class="submit-btn" type="submit">${hrL72('حفظ التسوية','Save settlement')}</button></div></form><div id="hr76SettlementPreview"></div>`;document.getElementById('addModalBody').classList.add('hr72-modal');document.getElementById('addModalOverlay').classList.remove('hidden');}
async function hrPreviewSettlementV76(){const g=id=>document.getElementById(id)?.value,n=id=>Number(g(id)||0),box=document.getElementById('hr76SettlementPreview');try{const {data,error}=await sb.rpc('tasky_hr_eos_calculate_v76',{p_employee_id:g('hr76SetEmp'),p_end_date:g('hr76SetEnd'),p_termination_reason:g('hr76SetReason'),p_worker_initiated:g('hr76WorkerInitiated')==='true',p_award_wage:n('hr76AwardWage'),p_unused_leave_days:n('hr76LeaveDays'),p_leave_daily_rate:n('hr76LeaveRate'),p_final_salary:n('hr76FinalSalary'),p_other_earnings:n('hr76OtherEarn'),p_other_deductions:n('hr76OtherDeduct'),p_manual_factor:g('hr76ManualFactor')===''?null:n('hr76ManualFactor')});if(error)throw error;box.innerHTML=`<div class="hr76-calc"><div><span>${hrL72('مدة الخدمة','Service')}</span><b>${Number(data.service_years||0).toFixed(2)} ${hrL72('سنة','years')}</b></div><div><span>${hrL72('مكافأة نهاية الخدمة','EOSB')}</span><b>${hrMoney72(data.eos_amount)}</b></div><div><span>${hrL72('بدل الإجازة','Leave encashment')}</span><b>${hrMoney72(data.leave_encashment)}</b></div><div class="total"><span>${hrL72('الإجمالي النهائي','Final total')}</span><b>${hrMoney72(data.total_payable)}</b></div></div><div class="hr76-review-note">${hrL72('معامل الاستحقاق','Entitlement factor')}: ${Number(data.eos_factor||0).toFixed(4)} · ${hrL72('آخر موعد مستهدف للتسوية','Target settlement deadline')}: ${hrDate72(data.settlement_due_date)}${data.note?`<br>${escapeHtml(data.note)}`:''}</div>`;}catch(err){box.innerHTML=`<div class="hr72-alert" style="margin-top:8px">${escapeHtml(err?.message||String(err))}</div>`;}}
