function hrContractsV77(){const rows=[...hrV72.contracts77].sort((a,b)=>String(b.start_date).localeCompare(String(a.start_date)));return `<div class="hr77-toolbar"><div><h3>${hrL72('سجل العقود وفترة التجربة','Contract & probation register')}</h3><div style="font-size:10px;color:var(--muted);margin-top:3px">${hrL72('مرجع داخلي لحالة العقد والتجربة ومرجع قوى. لا ينشئ أو يوثق العقد رسميًا.','Internal tracker for contract, probation and Qiwa reference. It does not authenticate a contract.')}</div></div><div class="hr77-toolbar-actions"><button class="primary-btn" onclick="hrOpenFormV72('contract77')">+ ${hrL72('عقد','Contract')}</button></div></div><div class="hr77-contract-grid">${rows.map(c=>{const e=hrEmp72(c.employee_id),endClass=hrDeadlineClassV77(c.end_date),probClass=hrDeadlineClassV77(c.probation_end_date);return `<div class="hr77-contract"><div class="hr77-contract-top"><div><h4>${escapeHtml(hrName72(e))}</h4><p>${escapeHtml(hrContractTypeV77(c.contract_type))} · ${hrDate72(c.start_date)}${c.end_date?` → ${hrDate72(c.end_date)}`:''}</p></div>${hrContractStatusV77(c.status)}</div><div class="hr77-contract-meta"><div><span>${hrL72('فترة التجربة','Probation')}</span><b>${hrProbationStatusV77(c.probation_status)}</b>${c.probation_end_date?`<small class="hr77-deadline ${probClass}">${hrDate72(c.probation_end_date)}</small>`:''}</div><div><span>${hrL72('إشعار الموظف/المنشأة','Employee / employer notice')}</span><b>${Number(c.employee_notice_days||0)} / ${Number(c.employer_notice_days||0)} ${hrL72('يوم','days')}</b></div><div><span>${hrL72('قوى','Qiwa')}</span><b>${escapeHtml(c.qiwa_status||'not_recorded')}</b><small>${escapeHtml(c.qiwa_contract_reference||'—')}</small></div></div>${c.end_date?`<div class="hr77-deadline ${endClass}" style="margin-top:8px">${hrL72('تاريخ الانتهاء','End date')}: ${hrDate72(c.end_date)}${hrDaysUntilV77(c.end_date)!==null?` · ${hrDaysUntilV77(c.end_date)} ${hrL72('يوم','days')}`:''}</div>`:''}<div class="hr77-contract-actions"><button class="platform-mini-btn" onclick="hrOpenFormV72('contract77','${c.id}')">${hrL72('تعديل','Edit')}</button><button class="platform-mini-btn" onclick="hrOpenFormV72('termination77',null,'${c.employee_id}')">${hrL72('إجراء إنهاء/عدم تجديد','Termination / non-renewal')}</button></div></div>`}).join('')||`<div class="hr72-empty">${hrL72('لا توجد عقود في السجل بعد.','No contracts in the register yet.')}</div>`}</div>`;}
function hrResignationsV77(){const rows=[...hrV72.resignations77].sort((a,b)=>String(b.submitted_at).localeCompare(String(a.submitted_at)));return `<div class="hr77-toolbar"><div><h3>${hrL72('طلبات الاستقالة','Resignation requests')}</h3><div style="font-size:10px;color:var(--muted);margin-top:3px">${hrL72('طلب الاستقالة لا يحتوي تاريخًا مؤجلًا يختاره الموظف. النظام يتابع نافذة السحب والاستجابة والتأجيل.','Employee requests do not include a deferred resignation date. Tasky tracks withdrawal, response and employer-deferral windows.')}</div></div><div class="hr77-toolbar-actions"><button class="primary-btn" onclick="hrOpenFormV72('resignation77')">+ ${hrL72('تسجيل استقالة','Record resignation')}</button></div></div><div class="hr77-card-list">${rows.map(r=>{const due=r.status==='deferred'?r.defer_until:r.response_due_date,dclass=hrDeadlineClassV77(due);return `<div class="hr77-card"><div class="hr77-card-main"><h4>${escapeHtml(hrName72(hrEmp72(r.employee_id)))} ${hrResignationStatusV77(r.status)}</h4><p>${hrL72('قُدمت','Submitted')}: ${hrDate72(r.submitted_at)}${r.employee_reason?` · ${escapeHtml(r.employee_reason)}`:''}</p></div><div class="hr77-card-stat"><span>${hrL72('آخر موعد للسحب','Withdrawal window')}</span><b>${hrDate72(r.withdrawal_deadline)}</b></div><div class="hr77-card-stat"><span>${r.status==='deferred'?hrL72('نهاية التأجيل','Deferral ends'):hrL72('حد الاستجابة','Response due')}</span><b class="hr77-deadline ${dclass}">${hrDate72(due)}</b></div><div class="hr77-card-stat"><span>${hrL72('نهاية العلاقة','Effective end')}</span><b>${hrDate72(r.effective_end_date)}</b></div><div class="hr77-card-actions">${r.status==='submitted'?`<button class="platform-mini-btn primary" onclick="hrResignationActionV77('${r.id}','accept')">${hrL72('قبول','Accept')}</button><button class="platform-mini-btn" onclick="hrOpenDeferResignationV77('${r.id}')">${hrL72('تأجيل','Defer')}</button>`:''}${r.status==='deferred'?`<button class="platform-mini-btn primary" onclick="hrResignationActionV77('${r.id}','accept')">${hrL72('قبول الآن','Accept now')}</button>`:''}${['submitted','deferred'].includes(r.status)?`<button class="platform-mini-btn danger" onclick="hrResignationActionV77('${r.id}','cancel_admin')">${hrL72('إلغاء إداري','Admin cancel')}</button>`:''}</div></div>${r.defer_explanation?`<div class="hr76-review-note">${escapeHtml(r.defer_explanation)}</div>`:''}`}).join('')||`<div class="hr72-empty">${hrL72('لا توجد طلبات استقالة.','No resignation requests.')}</div>`}</div>`;}
function hrTerminationsV77(){
  const rows=[...hrV72.terminationNotices77].sort((a,b)=>String(b.intended_end_date).localeCompare(String(a.intended_end_date)));
  const body=rows.map(n=>{
    const settlementBtn=n.final_settlement_id
      ? `<button class="platform-mini-btn" onclick="hrSetPayrollSubviewV76('settlements');setHrTabV72('compensation')">${hrL72('التسوية','Settlement')}</button>`
      : '';
    return `<div class="hr77-card"><div class="hr77-card-main"><h4>${escapeHtml(hrName72(hrEmp72(n.employee_id)))} ${hrNoticeStatusV77(n.status)}</h4><p>${escapeHtml(hrTerminationTypeV77(n.termination_type))} · ${hrDate72(n.notice_date)} → ${hrDate72(n.intended_end_date)}</p></div><div class="hr77-card-stat"><span>${hrL72('المطلوب / الفعلي','Required / actual')}</span><b>${Number(n.required_notice_days||0)} / ${Number(n.actual_notice_days||0)} ${hrL72('يوم','days')}</b></div><div class="hr77-card-stat"><span>${hrL72('النقص','Shortfall')}</span><b style="${Number(n.notice_shortfall_days||0)>0?'color:var(--danger)':''}">${Number(n.notice_shortfall_days||0)} ${hrL72('يوم','days')}</b></div><div class="hr77-card-stat"><span>${hrL72('فحص الامتثال','Compliance')}</span><b>${hrComplianceStatusV77(n.compliance_status)}</b></div><div class="hr77-card-actions"><button class="platform-mini-btn" onclick="hrOpenFormV72('termination77','${n.id}','${n.employee_id}')">${hrL72('تعديل','Edit')}</button>${settlementBtn}</div></div>${n.review_note?`<div class="hr76-review-note">${escapeHtml(n.review_note)}</div>`:''}`;
  }).join('');
  return `<div class="hr77-toolbar"><div><h3>${hrL72('الإنهاء وعدم التجديد وفترات الإشعار','Termination, non-renewal & notice periods')}</h3><div style="font-size:10px;color:var(--muted);margin-top:3px">${hrL72('للعقد غير محدد المدة والأجر الشهري: 30 يومًا إذا بدأ الموظف الإنهاء و60 يومًا إذا بدأ صاحب العمل. الحالات الأخرى قد تتطلب مراجعة العقد والنظام.','For indefinite monthly-paid contracts: 30 days when employee-initiated and 60 days when employer-initiated. Other cases may require contract/legal review.')}</div></div><div class="hr77-toolbar-actions"><button class="primary-btn" onclick="hrOpenFormV72('termination77')">+ ${hrL72('إجراء إنهاء','Termination record')}</button></div></div><div class="hr77-card-list">${body||`<div class="hr72-empty">${hrL72('لا توجد إجراءات إنهاء مسجلة.','No termination records.')}</div>`}</div>`;
}
function hrDisciplineV77(){const rows=[...hrV72.disciplinary77].sort((a,b)=>String(b.discovered_at).localeCompare(String(a.discovered_at)));return `<div class="hr77-toolbar"><div><h3>${hrL72('التحقيق والجزاءات والتظلمات','Investigations, sanctions & grievances')}</h3><div style="font-size:10px;color:var(--muted);margin-top:3px">${hrL72('تاسكي يفرض اكتمال إشعار التهمة وسماع دفاع الموظف وتوثيق المحضر والإشعار الكتابي قبل إغلاق إجراء تأديبي.','Tasky requires written-charge notice, employee defense/hearing, documented record and written decision notification before an action can be closed.')}</div></div><div class="hr77-toolbar-actions"><button class="primary-btn" onclick="hrOpenFormV72('discipline77')">+ ${hrL72('ملف تأديبي','Disciplinary case')}</button></div></div><div class="hr77-card-list">${rows.map(d=>{const acc=hrDeadlineClassV77(d.accusation_deadline),san=hrDeadlineClassV77(d.sanction_deadline);return `<div class="hr77-card"><div class="hr77-card-main"><h4>${escapeHtml(hrName72(hrEmp72(d.employee_id)))} · ${escapeHtml(d.violation_title)} ${hrDisciplineStatusV77(d.status)}</h4><p>${hrL72('اكتشاف','Discovered')}: ${hrDate72(d.discovered_at)} · ${escapeHtml(hrSanctionV77(d.sanction_type))}${d.needs_review?` · <span style="color:var(--danger);font-weight:800">${hrL72('مراجعة','Review')}</span>`:''}</p></div><div class="hr77-card-stat"><span>${hrL72('مهلة الاتهام التشغيلية','Charge guidance')}</span><b class="hr77-deadline ${acc}">${hrDate72(d.accusation_deadline)}</b></div><div class="hr77-card-stat"><span>${hrL72('مهلة الجزاء التشغيلية','Sanction guidance')}</span><b class="hr77-deadline ${san}">${hrDate72(d.sanction_deadline)}</b></div><div class="hr77-card-stat"><span>${hrL72('التظلم — تاريخ إرشادي','Grievance guide date')}</span><b>${hrDate72(d.grievance_guidance_date)}</b></div><div class="hr77-card-actions"><button class="platform-mini-btn" onclick="hrOpenFormV72('discipline77','${d.id}')">${hrL72('فتح/تعديل','Open / edit')}</button></div></div>${d.compliance_note?`<div class="hr76-review-note">${escapeHtml(d.compliance_note)}</div>`:''}`}).join('')||`<div class="hr72-empty">${hrL72('لا توجد ملفات تأديبية منظمة في V77.','No structured disciplinary cases in V77 yet.')}</div>`}</div>`;}

/* Employee self-service resignation card inside HR Requests */
const hrRequestsV72BaseV77=hrRequestsV72;
hrRequestsV72=function(){const base=hrRequestsV72BaseV77();if(!hrContextV72.employee_id)return base;const r=hrMyActiveResignationV77();const canWithdraw=r&&['submitted','deferred'].includes(r.status)&&hrDaysUntilV77(r.withdrawal_deadline)>=0;return `<div class="hr77-self"><div class="hr77-self-head"><div><h4>${hrL72('علاقتي الوظيفية','My employment relationship')}</h4><p>${r?hrL72('لديك طلب استقالة نشط ويمكن متابعة حالته هنا.','You have an active resignation request and can track it here.'):hrL72('يمكنك تقديم طلب استقالة رسمي داخليًا من هنا. التوثيق/الإنهاء الحكومي لا يتم تلقائيًا من تاسكي.','You can submit an internal resignation request here. Government contract termination is not performed automatically by Tasky.')}</p></div>${r?hrResignationStatusV77(r.status):''}</div>${r?`<div class="hr77-checklist"><div class="hr77-check"><b>${hrL72('تاريخ التقديم','Submitted')}</b><br>${hrDate72(r.submitted_at)}</div><div class="hr77-check"><b>${hrL72('نافذة السحب','Withdrawal window')}</b><br>${hrDate72(r.withdrawal_deadline)}</div><div class="hr77-check"><b>${r.status==='deferred'?hrL72('نهاية التأجيل','Deferral ends'):hrL72('حد الاستجابة','Response due')}</b><br>${hrDate72(r.status==='deferred'?r.defer_until:r.response_due_date)}</div><div class="hr77-check"><b>${hrL72('النهاية الفعلية','Effective end')}</b><br>${hrDate72(r.effective_end_date)}</div></div><div class="hr77-self-actions">${canWithdraw?`<button class="chip-btn" onclick="hrResignationActionV77('${r.id}','withdraw')">${hrL72('سحب طلب الاستقالة','Withdraw resignation')}</button>`:''}</div>`:`<div class="hr77-self-actions"><button class="primary-btn" onclick="hrOpenFormV72('resignation77')">${hrL72('تقديم استقالة','Submit resignation')}</button></div>`}</div>${base}`;};

/* Fetch V77 tables + derived compliance summary */
const fetchHrDataV72BaseV77=fetchHrDataV72;
fetchHrDataV72=async function(force=false){
  if(currentWorkspaceId&&hrCanManage72()&&(force||hrLoadedWorkspaceV72!==currentWorkspaceId)){const rr=await sb.rpc('tasky_hr_refresh_relations_v77',{p_workspace_id:currentWorkspaceId});if(rr.error&&/does not exist|schema cache|tasky_hr_/i.test(rr.error.message||'')){hrMigrationMissingV72=true;}}
  await fetchHrDataV72BaseV77(force);
  if(currentWorkspaceId&&hrCanManage72()&&!hrMigrationMissingV72){const q=await sb.rpc('tasky_hr_compliance_summary_v77',{p_workspace_id:currentWorkspaceId});if(!q.error)hrComplianceSummaryV77=q.data||hrComplianceSummaryV77;else if(/does not exist|schema cache|tasky_hr_/i.test(q.error.message||''))hrMigrationMissingV72=true;}
  if(activeNav==='hr')renderModule();
};
async function hrRefreshRelationsV77(){try{const {error}=await sb.rpc('tasky_hr_refresh_relations_v77',{p_workspace_id:currentWorkspaceId});if(error)throw error;await fetchHrDataV72(true);taskyToast(hrL72('تم تحديث المهل وحالات الاستقالة','Deadlines and resignation statuses refreshed'),{tone:'success'});}catch(err){showTaskyDialog({title:'HR V77',message:err?.message||String(err),tone:'error'});}}

/* Forms */
function hrEmpOptionsV77(selected=''){return hrV72.employees.filter(e=>e.status!=='terminated'||String(e.id)===String(selected)).map(e=>`<option value="${e.id}" ${String(e.id)===String(selected)?'selected':''}>${escapeHtml(hrName72(e))}${e.employee_no?` — ${escapeHtml(e.employee_no)}`:''}</option>`).join('');}
function hrContractOptionsV77(empId,selected=''){return `<option value="">${hrL72('بدون عقد محدد','No specific contract')}</option>`+hrV72.contracts77.filter(c=>!empId||String(c.employee_id)===String(empId)).map(c=>`<option value="${c.id}" ${String(c.id)===String(selected)?'selected':''}>${escapeHtml(hrName72(hrEmp72(c.employee_id)))} · ${escapeHtml(hrContractTypeV77(c.contract_type))} · ${hrDate72(c.start_date)}</option>`).join('');}
function hrOpenContractFormV77(id=null){const c=id?hrV72.contracts77.find(x=>String(x.id)===String(id)):null;document.getElementById('addModalBody').innerHTML=`<div class="modal-head"><div><h3>${c?hrL72('تعديل سجل العقد','Edit contract record'):hrL72('إضافة سجل عقد','Add contract record')}</h3><div style="font-size:9px;color:var(--muted)">${hrL72('سجل تشغيلي داخلي — لا ينشئ عقد قوى','Internal operational record — does not create a Qiwa contract')}</div></div><button class="modal-close" onclick="closeAddModal()"><svg style="width:18px"><use href="#i-x"/></svg></button></div><form onsubmit="hrSubmitFormV72(event,'contract77','${c?.id||''}')"><div class="hr72-form">${hrSelect72('hr77ContractEmp',hrL72('الموظف','Employee'),hrEmpOptionsV77(c?.employee_id),true)}${hrSelect72('hr77ContractType',hrL72('نوع العقد','Contract type'),`<option value="fixed" ${c?.contract_type!=='indefinite'?'selected':''}>${hrL72('محدد المدة','Fixed-term')}</option><option value="indefinite" ${c?.contract_type==='indefinite'?'selected':''}>${hrL72('غير محدد المدة','Indefinite')}</option>`)}${hrSelect72('hr77ContractStatus',hrL72('الحالة الداخلية','Internal status'),['draft','pending_auth','active','expired','terminated','cancelled'].map(x=>`<option value="${x}" ${(c?.status||'draft')===x?'selected':''}>${x}</option>`).join(''))}${hrField72('hr77ContractStart',hrL72('تاريخ البداية','Start date'),c?.start_date||'','date',true)}${hrField72('hr77ContractEnd',hrL72('تاريخ النهاية — للعقد المحدد','End date — fixed term'),c?.end_date||'','date')}${hrSelect72('hr77PayFrequency',hrL72('دورية الأجر','Pay frequency'),`<option value="monthly" ${(c?.pay_frequency||'monthly')==='monthly'?'selected':''}>${hrL72('شهري','Monthly')}</option><option value="other" ${c?.pay_frequency==='other'?'selected':''}>${hrL72('غير شهري','Other')}</option>`)}${hrField72('hr77ProbationDays',hrL72('مدة التجربة بالأيام — حد أقصى 180','Probation days — max 180'),Number(c?.probation_days||0),'number')}${hrField72('hr77ProbationStart',hrL72('بداية التجربة','Probation start'),c?.probation_start_date||'','date')}${hrSelect72('hr77ProbationStatus',hrL72('حالة التجربة','Probation status'),['not_applicable','active','passed','extended','terminated'].map(x=>`<option value="${x}" ${(c?.probation_status||'not_applicable')===x?'selected':''}>${x}</option>`).join(''))}${hrField72('hr77EmployeeNotice',hrL72('إشعار الموظف — أيام','Employee notice — days'),c?.employee_notice_days??30,'number')}${hrField72('hr77EmployerNotice',hrL72('إشعار صاحب العمل — أيام','Employer notice — days'),c?.employer_notice_days??60,'number')}${hrField72('hr77NonrenewalNotice',hrL72('إشعار عدم التجديد التعاقدي — أيام','Contractual non-renewal notice — days'),c?.nonrenewal_notice_days??0,'number')}${hrSelect72('hr77RenewalMode',hrL72('التجديد','Renewal'),['manual','auto','none'].map(x=>`<option value="${x}" ${(c?.renewal_mode||'manual')===x?'selected':''}>${x}</option>`).join(''))}${hrField72('hr77QiwaRef',hrL72('مرجع عقد قوى — إن وجد','Qiwa contract reference — if available'),c?.qiwa_contract_reference||'')}${hrSelect72('hr77QiwaStatus',hrL72('حالة قوى المسجلة يدويًا','Manually recorded Qiwa status'),['not_recorded','draft','sent','authenticated','active','terminated','cancelled','other'].map(x=>`<option value="${x}" ${(c?.qiwa_status||'not_recorded')===x?'selected':''}>${x}</option>`).join(''))}${hrField72('hr77QiwaVerified',hrL72('آخر تحقق من قوى','Last Qiwa verification'),c?.qiwa_last_verified_at?String(c.qiwa_last_verified_at).slice(0,16):'','datetime-local')}<div class="field full"><label>${hrL72('ملاحظات','Notes')}</label><textarea id="hr77ContractNotes">${escapeHtml(c?.notes||'')}</textarea></div></div><div class="hr77-modal-note">${hrL72('تاسكي يحد مدة التجربة المدخلة إلى 180 يومًا ويستخدم فترات الإشعار المسجلة كأداة تشغيلية. يجب أن تطابق البيانات العقد الفعلي وحالته الرسمية.','Tasky caps entered probation at 180 days and uses recorded notice periods as an operational aid. Data must match the actual contract and its official status.')}</div><button class="submit-btn" type="submit">${hrL72('حفظ سجل العقد','Save contract record')}</button></form>`;document.getElementById('addModalBody').classList.add('hr72-modal');document.getElementById('addModalOverlay').classList.remove('hidden');}
function hrOpenResignationFormV77(){const own=!hrCanManage72()&&hrContextV72.employee_id;document.getElementById('addModalBody').innerHTML=`<div class="modal-head"><div><h3>${hrL72('طلب استقالة','Resignation request')}</h3><div style="font-size:9px;color:var(--muted)">${hrL72('لا تضف تاريخ استقالة مؤجل داخل الطلب','Do not specify a deferred resignation date in the request')}</div></div><button class="modal-close" onclick="closeAddModal()"><svg style="width:18px"><use href="#i-x"/></svg></button></div><form onsubmit="hrSubmitFormV72(event,'resignation77')"><div class="hr72-form">${own?`<input id="hr77ResEmp" type="hidden" value="${own}">`+`<div class="field full"><label>${hrL72('الموظف','Employee')}</label><div class="hr77-modal-note">${escapeHtml(hrName72(hrEmp72(own)))}</div></div>`:hrSelect72('hr77ResEmp',hrL72('الموظف','Employee'),hrEmpOptionsV77(),true)}${hrField72('hr77ResReason',hrL72('سبب مختصر — اختياري','Brief reason — optional'),'')}<div class="field full"><label>${hrL72('ملاحظات الموظف','Employee notes')}</label><textarea id="hr77ResNotes"></textarea></div></div><div class="hr77-modal-note">${hrL72('بعد التقديم يتابع تاسكي نافذة السحب لمدة 7 أيام وحد الاستجابة لمدة 30 يومًا. التوثيق الرسمي لإنهاء العقد لا يتم من داخل تاسكي.','After submission, Tasky tracks the 7-day withdrawal window and 30-day response window. Official contract termination is not submitted from Tasky.')}</div><button class="submit-btn" type="submit">${hrL72('إرسال طلب الاستقالة','Submit resignation')}</button></form>`;document.getElementById('addModalBody').classList.add('hr72-modal');document.getElementById('addModalOverlay').classList.remove('hidden');}
