fetchHrDataV72=async function(force=false){await fetchHrDataV72BaseV78(force);if(!currentWorkspaceId||hrMigrationMissingV72)return;try{await sb.rpc('tasky_hr_seed_documents_v78',{p_workspace_id:currentWorkspaceId});if(hrCanManage72())await sb.rpc('tasky_hr_refresh_document_alerts_v78',{p_workspace_id:currentWorkspaceId});const keys=['documentTypes78','documentVersions78','documentAlerts78','documentRequests78','documentTemplates78','documentIssuances78','documentAudit78'];const qs=await Promise.all(keys.map(async k=>[k,await sb.from(hrTablesV72[k]).select('*').eq('workspace_id',currentWorkspaceId).limit(2000)]));for(const [k,q] of qs){if(q.error){if(/does not exist|schema cache|tasky_hr_/i.test(q.error.message||'')){hrMigrationMissingV72=true;break;}hrV72[k]=[];}else hrV72[k]=q.data||[];}}catch(err){if(/does not exist|schema cache|tasky_hr_/i.test(err?.message||''))hrMigrationMissingV72=true;console.warn('HR V78',err);}if(activeNav==='hr')renderModule();};
const hrTemplateV72BaseV78=hrTemplateV72;
hrTemplateV72=function(){if(hrMigrationMissingV72)return `<div class="hr72-shell">${hrHeaderV72()}<div class="hr72-panel"><div class="hr72-alert">${hrL72('بيانات V78 لمركز الوثائق غير مثبتة أو غير مكتملة. شغّل SQL الخاص بـ V78 بعد V77 ثم أعد المحاولة.','V78 Document Center data is not installed or incomplete. Run the V78 SQL after V77, then retry.')}</div><button class="primary-btn" style="margin-top:12px" onclick="fetchHrDataV72(true)">${hrL72('إعادة المحاولة','Retry')}</button></div></div>`;return hrTemplateV72BaseV78();};



