const hrBodyV72BaseV79=hrBodyV72;
hrBodyV72=function(){if(hrActiveTabV72==='automation79')return hrAutomationV79();return hrBodyV72BaseV79();};

function hr79Bool(v,d=true){return v===undefined||v===null?d:!!v;}
function hr79Arr(v,fallback){return Array.isArray(v)&&v.length?v:fallback;}
function hr79Status(v){const m={open:['مفتوح','Open','warning'],acknowledged:['تم الاستلام','Acknowledged','ok'],resolved:['مغلق','Resolved','ok']};const x=m[v]||[v||'—',v||'—',''];return `<span class="hr79-chip ${x[2]}">${hrL72(x[0],x[1])}</span>`;}
function hr79Severity(v){const m={critical:['حرج','Critical'],warning:['تنبيه','Warning'],info:['معلومة','Info']};return hrL72(...(m[v]||[v||'—',v||'—']));}
function hr79SourceLabel(v){const m={document:['وثيقة','Document'],contract:['عقد','Contract'],probation:['فترة تجربة','Probation'],resignation:['استقالة','Resignation'],termination:['إنهاء علاقة','Termination'],document_request:['طلب مستند','Document request']};return hrL72(...(m[v]||[v||'—',v||'—']));}
function hr79UserName(uid){return taskMemberById(uid)?.fullName||taskMemberById(uid)?.email||'—';}
function hr79DateTime(v){return v?formatDateTime(v):'—';}
function hr79DaysText(v){if(v===null||v===undefined)return '—';const n=Number(v);return n<0?hrL72(`متأخر ${Math.abs(n)} يوم`,`Overdue ${Math.abs(n)}d`):hrL72(`${n} يوم`,` ${n}d`);}

async function fetchHrAutomationV79(force=false){
  if(!currentWorkspaceId||!hrCanManage72())return;
  if(hrAutomationLoadingV79)return;
  if(!force&&hrAutomationLoadedWorkspaceV79===currentWorkspaceId&&!hrAutomationMissingV79)return;
  hrAutomationLoadingV79=true;hrAutomationMissingV79=false;
  try{
    const seed=await sb.rpc('tasky_hr_seed_automation_v79',{p_workspace_id:currentWorkspaceId});
    if(seed.error)throw seed.error;
    const [settingsRes,eventsRes,actionsRes,runsRes,summaryRes,schedulerRes]=await Promise.all([
      sb.from('tasky_hr_automation_settings_v79').select('*').eq('workspace_id',currentWorkspaceId).maybeSingle(),
      sb.from('tasky_hr_automation_events_v79').select('*').eq('workspace_id',currentWorkspaceId).order('created_at',{ascending:false}).limit(250),
      sb.from('tasky_hr_automation_actions_v79').select('*').eq('workspace_id',currentWorkspaceId).order('created_at',{ascending:false}).limit(200),
      sb.from('tasky_hr_automation_runs_v79').select('*').eq('workspace_id',currentWorkspaceId).order('started_at',{ascending:false}).limit(20),
      sb.rpc('tasky_hr_automation_summary_v79',{p_workspace_id:currentWorkspaceId}),
      sb.rpc('tasky_hr_scheduler_status_v79',{p_workspace_id:currentWorkspaceId})
    ]);
    const anyErr=[settingsRes,eventsRes,actionsRes,runsRes,summaryRes,schedulerRes].find(x=>x?.error);
    if(anyErr?.error)throw anyErr.error;
    hrAutoV79.settings=settingsRes.data||null;hrAutoV79.events=eventsRes.data||[];hrAutoV79.actions=actionsRes.data||[];hrAutoV79.runs=runsRes.data||[];hrAutoV79.summary=summaryRes.data||{};hrAutoV79.scheduler=schedulerRes.data||{cron_installed:false,job:null};
    hrAutomationLoadedWorkspaceV79=currentWorkspaceId;
  }catch(err){
    console.warn('HR V79 automation unavailable',err);
    hrAutomationMissingV79=/does not exist|schema cache|tasky_hr_automation|tasky_hr_seed_automation/i.test(err?.message||'');
  }finally{hrAutomationLoadingV79=false;if(activeNav==='hr'&&hrActiveTabV72==='automation79')renderModule();}
}

const fetchHrDataV72BaseV79=fetchHrDataV72;
fetchHrDataV72=async function(force=false){await fetchHrDataV72BaseV79(force);if(currentWorkspaceId&&hrCanManage72()&&!hrMigrationMissingV72)await fetchHrAutomationV79(force);};

function hrAutomationV79(){
  if(hrAutomationMissingV79)return `<div class="hr79-missing"><h3>${hrL72('V79 غير مثبت بعد','V79 is not installed yet')}</h3><p>${hrL72('شغّل SQL الخاص بـ V79 بعد V78. بقية أقسام HR ستبقى تعمل بدون تعطيل.','Run the V79 SQL migration after V78. The rest of HR remains available without being blocked.')}</p><button class="primary-btn" style="margin-top:12px" onclick="fetchHrAutomationV79(true)">${hrL72('إعادة المحاولة','Retry')}</button></div>`;
  if(hrAutomationLoadingV79&&!hrAutoV79.settings)return `<div class="hr72-panel"><div class="hr72-empty">${hrL72('جارٍ تحميل محرك الأتمتة...','Loading automation engine...')}</div></div>`;
  const s=hrAutoV79.summary||{},cfg=hrAutoV79.settings||{};
  const openEvents=hrAutoV79.events.filter(e=>['open','acknowledged'].includes(e.status));
  const openActions=hrAutoV79.actions.filter(a=>['open','in_progress'].includes(a.status));
  return `<div class="hr79-shell"><div class="hr79-note"><b>${hrL72('V79 — أتمتة HR خاصة وآمنة.','V79 — private HR automation.')}</b> ${hrL72('التنبيهات تصل إلى مركز إشعارات تاسكي وتُنشىء إجراءات داخل HR فقط حتى لا تتسرب بيانات حساسة إلى مشروع عام. لا يوجد إرسال بريد/SMS أو إجراء حكومي تلقائي في هذه المرحلة.','Alerts are merged into Tasky notifications and create private HR actions only, avoiding sensitive-data leakage into general projects. No email/SMS or government action is automated in this release.')}</div><div class="hr79-kpis"><div class="hr79-kpi ${Number(s.open_events||0)?'warn':''}"><span>${hrL72('تنبيهات مفتوحة','Open alerts')}</span><b>${Number(s.open_events||0)}</b></div><div class="hr79-kpi ${Number(s.critical_events||0)?'bad':''}"><span>${hrL72('حرجة','Critical')}</span><b>${Number(s.critical_events||0)}</b></div><div class="hr79-kpi ${Number(s.escalated_events||0)?'bad':''}"><span>${hrL72('تم تصعيدها','Escalated')}</span><b>${Number(s.escalated_events||0)}</b></div><div class="hr79-kpi"><span>${hrL72('إجراءات HR مفتوحة','Open HR actions')}</span><b>${Number(s.open_actions||0)}</b></div><div class="hr79-kpi ${Number(s.overdue_actions||0)?'bad':''}"><span>${hrL72('إجراءات متأخرة','Overdue actions')}</span><b>${Number(s.overdue_actions||0)}</b></div><div class="hr79-kpi"><span>${hrL72('آخر تشغيل','Last run')}</span><b style="font-size:10px;line-height:1.6">${escapeHtml(hr79DateTime(cfg.last_run_at||s.last_run_at))}</b></div></div><div class="hr79-grid"><div class="hr79-panel">${hr79EventsHtml(openEvents)}</div><div class="hr79-panel">${hr79ActionsHtml(openActions)}</div><div class="hr79-panel">${hr79SettingsHtml(cfg)}</div><div class="hr79-panel">${hr79SchedulerHtml()}</div></div></div>`;
}

function hr79EventsHtml(rows){return `<div class="hr79-head"><div><h3>${hrL72('التنبيهات النشطة','Active automation alerts')}</h3><p>${hrL72('وثائق، عقود، تجربة، استقالات، إنهاء وطلبات مستندات متأخرة.','Documents, contracts, probation, resignations, exits and stale document requests.')}</p></div><div class="hr79-head-actions"><button class="primary-btn" onclick="hr79RunNow()">${hrL72('تشغيل الآن','Run now')}</button><button class="chip-btn" onclick="fetchHrAutomationV79(true)">${hrL72('تحديث','Refresh')}</button></div></div><div class="hr79-list">${rows.slice(0,60).map(e=>`<div class="hr79-event ${escapeHtml(e.severity||'')}"><div class="hr79-event-main"><div class="hr79-event-title"><b>${escapeHtml(hrL72(e.title_ar,e.title_en))}</b>${hr79Status(e.status)}<span class="hr79-chip ${escapeHtml(e.severity||'')}">${escapeHtml(hr79Severity(e.severity))}</span>${e.escalated_at?`<span class="hr79-chip critical">${hrL72('مصعّد','Escalated')}</span>`:''}</div><p>${escapeHtml(hrL72(e.message_ar,e.message_en)||'')}</p><div class="hr79-event-meta"><span class="hr79-chip">${escapeHtml(hr79SourceLabel(e.target_type))}</span>${e.due_date?`<span class="hr79-chip">${hrL72('الاستحقاق','Due')}: ${escapeHtml(hrDate72(e.due_date))}</span>`:''}${e.days_remaining!==null?`<span class="hr79-chip">${escapeHtml(hr79DaysText(e.days_remaining))}</span>`:''}<span class="hr79-chip">${escapeHtml(hr79DateTime(e.first_triggered_at))}</span></div></div><div class="hr79-event-actions"><button class="platform-mini-btn" onclick="hr79OpenSource('${e.id}')">${hrL72('فتح المصدر','Open source')}</button>${e.status==='open'?`<button class="platform-mini-btn primary" onclick="hr79EventAction('${e.id}','acknowledge')">${hrL72('استلام','Acknowledge')}</button>`:''}<button class="platform-mini-btn" onclick="hr79EventAction('${e.id}','resolve')">${hrL72('إغلاق التنبيه','Resolve')}</button></div></div>`).join('')||`<div class="hr72-empty">${hrL72('لا توجد تنبيهات أتمتة مفتوحة حاليًا.','No active automation alerts right now.')}</div>`}</div>`;}

function hr79ActionsHtml(rows){return `<div class="hr79-head"><div><h3>${hrL72('إجراءات HR التلقائية','Private HR actions')}</h3><p>${hrL72('مهام متابعة داخل HR فقط، ولا تظهر في مشاريع عامة.','Follow-up actions kept inside HR only, not general projects.')}</p></div></div><div class="hr79-list">${rows.slice(0,40).map(a=>`<div class="hr79-action"><div><b>${escapeHtml(hrL72(a.title_ar,a.title_en))}</b><small>${hrL72('المسؤول','Owner')}: ${escapeHtml(hr79UserName(a.assigned_to))} · ${hrL72('الاستحقاق','Due')}: ${escapeHtml(hrDate72(a.due_date))} · ${escapeHtml(a.priority||'')}</small></div><select onchange="hr79ActionStatus('${a.id}',this.value)"><option value="open" ${a.status==='open'?'selected':''}>${hrL72('مفتوح','Open')}</option><option value="in_progress" ${a.status==='in_progress'?'selected':''}>${hrL72('قيد التنفيذ','In progress')}</option><option value="done" ${a.status==='done'?'selected':''}>${hrL72('منجز','Done')}</option><option value="cancelled" ${a.status==='cancelled'?'selected':''}>${hrL72('ملغي','Cancelled')}</option></select></div>`).join('')||`<div class="hr72-empty">${hrL72('لا توجد إجراءات متابعة مفتوحة.','No open follow-up actions.')}</div>`}</div>`;}

function hr79SettingsHtml(c){
  const ownerOptions=`<option value="">${hrL72('تلقائي — أول HR Manager/Admin','Automatic — first HR Manager/Admin')}</option>`+assignableMembers().map(m=>`<option value="${m.userId}" ${String(c.action_owner_user_id||'')===String(m.userId)?'selected':''}>${escapeHtml(m.fullName||m.email)}</option>`).join('');
  const ck=(id,label,val)=>`<label class="hr79-check"><input id="${id}" type="checkbox" ${hr79Bool(val)?'checked':''}>${label}</label>`;
  const arr=v=>escapeHtml(hr79Arr(v,[]).join(','));
  return `<div class="hr79-head"><div><h3>${hrL72('إعدادات الأتمتة','Automation settings')}</h3><p>${hrL72('يمكن إيقاف نوع معين من التنبيه أو تغيير المستلمين والتصعيد.','Enable/disable trigger families and tune recipients/escalation.')}</p></div></div><form onsubmit="hr79SaveSettings(event)"><div class="hr79-settings-grid"><div class="hr79-settings-card"><h4>${hrL72('المصادر','Triggers')}</h4>${ck('hr79Enabled',hrL72('تشغيل محرك HR Automation','Enable HR automation'),c.enabled)}${ck('hr79Docs',hrL72('انتهاء الوثائق','Document expiry'),c.documents_enabled)}${ck('hr79Contracts',hrL72('انتهاء العقود','Contract expiry'),c.contracts_enabled)}${ck('hr79Probation',hrL72('نهاية فترة التجربة','Probation end'),c.probation_enabled)}${ck('hr79Resignations',hrL72('متابعة الاستقالات','Resignation follow-up'),c.resignations_enabled)}${ck('hr79Terminations',hrL72('مواعيد إنهاء العلاقة','Employment exit dates'),c.terminations_enabled)}${ck('hr79DocRequests',hrL72('طلبات الخطابات المتأخرة','Stale document requests'),c.document_requests_enabled)}</div><div class="hr79-settings-card"><h4>${hrL72('المستلمون والإجراءات','Recipients & actions')}</h4>${ck('hr79NotifyHr',hrL72('إشعار فريق HR','Notify HR'),c.notify_hr)}${ck('hr79NotifyManager',hrL72('تذكير المدير المباشر','Notify direct manager'),c.notify_manager)}${ck('hr79NotifyEmployee',hrL72('إشعار الموظف عندما يكون الحدث خاصًا به','Notify employee for employee-scoped events'),c.notify_employee)}${ck('hr79AutoActions',hrL72('إنشاء إجراء متابعة خاص داخل HR','Create private HR follow-up action'),c.auto_create_actions)}<div class="hr79-field"><label>${hrL72('المسؤول الافتراضي عن الإجراءات','Default action owner')}</label><select id="hr79Owner">${ownerOptions}</select></div><div class="hr79-field"><label>${hrL72('إنشاء الإجراء عندما يصبح الاستحقاق خلال','Create action when due within')}</label><input id="hr79ActionDays" type="number" min="0" max="180" value="${Number(c.action_due_days_before??30)}"></div></div><div class="hr79-settings-card"><h4>${hrL72('التصعيد','Escalation')}</h4><div class="hr79-field"><label>${hrL72('التصعيد لمسؤولي مساحة العمل إذا لم يتم الاستلام خلال (أيام)','Escalate to workspace admins if unacknowledged for (days)')}</label><input id="hr79EscDays" type="number" min="1" max="30" value="${Number(c.escalation_after_days??3)}"></div><div class="hr79-field"><label>${hrL72('اعتبار طلب المستند متأخرًا بعد (أيام)','Document request becomes stale after (days)')}</label><input id="hr79ReqDays" type="number" min="1" max="30" value="${Number(c.request_stale_days??3)}"></div><div class="hr79-field"><label>${hrL72('المنطقة الزمنية','Timezone')}</label><input id="hr79Timezone" value="${escapeHtml(c.timezone||'Asia/Riyadh')}"></div></div><div class="hr79-settings-card"><h4>${hrL72('مراحل التذكير — أيام قبل الموعد','Reminder stages — days before due date')}</h4><div class="hr79-field"><label>${hrL72('الوثائق','Documents')}</label><input id="hr79DocDays" value="${arr(c.document_reminder_days||[90,60,30,7,0])}"></div><div class="hr79-field"><label>${hrL72('العقود','Contracts')}</label><input id="hr79ContractDays" value="${arr(c.contract_reminder_days||[90,60,30,7,0])}"></div><div class="hr79-field"><label>${hrL72('فترة التجربة','Probation')}</label><input id="hr79ProbDays" value="${arr(c.probation_reminder_days||[30,14,7,3,0])}"></div><div class="hr79-field"><label>${hrL72('الإنهاء','Termination')}</label><input id="hr79TermDays" value="${arr(c.termination_reminder_days||[30,14,7,0])}"></div><div class="hr79-field"><label>${hrL72('الاستقالة','Resignation')}</label><input id="hr79ResDays" value="${arr(c.resignation_reminder_days||[7,3,1,0])}"></div></div></div><div class="hr79-settings-actions"><button class="submit-btn" style="width:auto;min-width:150px" type="submit">${hrL72('حفظ الإعدادات','Save settings')}</button></div></form>`;
}

function hr79SchedulerHtml(){const sc=hrAutoV79.scheduler||{},job=sc.job||null,runs=hrAutoV79.runs||[];return `<div class="hr79-head"><div><h3>${hrL72('المجدول وسجل التشغيل','Scheduler & run history')}</h3><p>${hrL72('المجدول يستخدم Supabase Cron عند توفر pg_cron.','Background execution uses Supabase Cron when pg_cron is available.')}</p></div></div><div class="hr79-scheduler"><div><span>${hrL72('Supabase Cron','Supabase Cron')}</span><b>${sc.cron_installed?(job&&job.active?hrL72('مفعّل','Enabled'):hrL72('الامتداد موجود — تحقق من Job','Extension installed — check job')):hrL72('غير مفعّل/غير متاح','Not enabled / unavailable')}</b></div><div><span>${hrL72('الجدول','Schedule')}</span><b>${escapeHtml(job?.schedule||sc.recommended_schedule||'5 5 * * *')} · ${hrL72('UTC','UTC')}</b></div><div><span>${hrL72('اسم المهمة','Job name')}</span><b>${escapeHtml(job?.jobname||'tasky-v79-hr-automation-daily')}</b></div><div><span>${hrL72('ملاحظة المنطقة الزمنية','Timezone note')}</span><b>${escapeHtml(hrL72('05:05 UTC = 08:05 بتوقيت الرياض. أحداث V79 تعتمد على التاريخ، وإعداد المنطقة الزمنية محفوظ للمراحل القادمة.','05:05 UTC = 08:05 Riyadh. V79 events are date-based; workspace timezone is stored for future time-sensitive automation.'))}</b></div></div>${!sc.cron_installed?`<div class="hr79-note" style="margin-top:10px;background:var(--amber-tint);border-color:color-mix(in srgb,var(--amber) 30%,var(--border))"><b>${hrL72('المجدول الخلفي غير مؤكد.','Background scheduler is not confirmed.')}</b> ${hrL72('فعّل Supabase Cron / pg_cron من Integrations ثم أعد تشغيل Migration V79 أو شغّل المحرك يدويًا من زر «تشغيل الآن».','Enable Supabase Cron / pg_cron from Integrations, then re-run the V79 migration or use “Run now” manually.')}</div>`:''}<div class="hr79-run-list">${runs.slice(0,8).map(r=>`<div class="hr79-run"><span class="hr79-chip ${r.status==='failed'?'critical':r.status==='completed'?'ok':''}">${escapeHtml(r.status)}</span><div><b>${escapeHtml(hr79DateTime(r.started_at))}</b><span> · ${r.events_seen||0} ${hrL72('تنبيه','events')} · ${r.notifications_created||0} ${hrL72('إشعار','notifications')} · ${r.actions_created||0} ${hrL72('إجراء','actions')}</span></div><span>${escapeHtml(r.run_type||'')}</span></div>`).join('')||`<div class="hr72-empty">${hrL72('لا يوجد سجل تشغيل بعد.','No run history yet.')}</div>`}</div>`;}

function hr79ParseDays(id,fallback){const raw=String(document.getElementById(id)?.value||'').split(',').map(x=>Number(x.trim())).filter(x=>Number.isInteger(x)&&x>=0&&x<=365);return raw.length?[...new Set(raw)].sort((a,b)=>b-a):fallback;}
async function hr79SaveSettings(e){e.preventDefault();const b=id=>!!document.getElementById(id)?.checked;const payload={enabled:b('hr79Enabled'),documents_enabled:b('hr79Docs'),contracts_enabled:b('hr79Contracts'),probation_enabled:b('hr79Probation'),resignations_enabled:b('hr79Resignations'),terminations_enabled:b('hr79Terminations'),document_requests_enabled:b('hr79DocRequests'),notify_hr:b('hr79NotifyHr'),notify_manager:b('hr79NotifyManager'),notify_employee:b('hr79NotifyEmployee'),auto_create_actions:b('hr79AutoActions'),action_owner_user_id:document.getElementById('hr79Owner')?.value||null,action_due_days_before:Number(document.getElementById('hr79ActionDays')?.value||30),escalation_after_days:Number(document.getElementById('hr79EscDays')?.value||3),request_stale_days:Number(document.getElementById('hr79ReqDays')?.value||3),timezone:document.getElementById('hr79Timezone')?.value.trim()||'Asia/Riyadh',document_reminder_days:hr79ParseDays('hr79DocDays',[90,60,30,7,0]),contract_reminder_days:hr79ParseDays('hr79ContractDays',[90,60,30,7,0]),probation_reminder_days:hr79ParseDays('hr79ProbDays',[30,14,7,3,0]),termination_reminder_days:hr79ParseDays('hr79TermDays',[30,14,7,0]),resignation_reminder_days:hr79ParseDays('hr79ResDays',[7,3,1,0])};try{const {error}=await sb.rpc('tasky_hr_save_automation_settings_v79',{p_workspace_id:currentWorkspaceId,p_payload:payload});if(error)throw error;hrAutomationLoadedWorkspaceV79=null;await fetchHrAutomationV79(true);taskyToast(hrL72('تم حفظ إعدادات الأتمتة','Automation settings saved'),{tone:'success'});}catch(err){showTaskyDialog({title:'HR V79',message:err?.message||String(err),tone:'error'});}}
