function hr80Pad(n){return String(n).padStart(2,'0');}
function hr80Ymd(d){return `${d.getFullYear()}-${hr80Pad(d.getMonth()+1)}-${hr80Pad(d.getDate())}`;}
function hr80Date(s){const [y,m,d]=String(s||'').split('-').map(Number);return y&&m&&d?new Date(y,m-1,d):null;}
function hr80AddDays(d,n){const x=new Date(d.getFullYear(),d.getMonth(),d.getDate());x.setDate(x.getDate()+n);return x;}
function hr80StartWeek(d){const x=new Date(d.getFullYear(),d.getMonth(),d.getDate());x.setDate(x.getDate()-x.getDay());return x;}
function hr80Range(){if(hrCalendarViewV80==='month'){const f=new Date(hrCalendarCursorV80.getFullYear(),hrCalendarCursorV80.getMonth(),1);f.setDate(f.getDate()-f.getDay());return {from:f,to:hr80AddDays(f,41)};}const f=hr80StartWeek(hrCalendarCursorV80);return {from:f,to:hr80AddDays(f,6)};}
function hr80LoadedKey(){const r=hr80Range();return [currentWorkspaceId,hrCalendarViewV80,hr80Ymd(r.from),hr80Ymd(r.to),hrCalendarSourceV80,hrCalendarEmployeeV80,hrCalendarDepartmentV80].join('|');}
function hr80EventTitle(e){return String(lang==='ar'?(e.title_ar||e.title_en):(e.title_en||e.title_ar)||'').trim()||hrL72('موعد HR','HR event');}
function hr80EmpName(e){return String(lang==='ar'?(e?.meta?.employee_name_ar||e?.meta?.employee_name_en):(e?.meta?.employee_name_en||e?.meta?.employee_name_ar)||'').trim();}
function hr80SourceLabel(s){const m={all:['كل المصادر','All sources'],manual:['أحداث HR','HR events'],leave:['الإجازات','Leave'],shift:['الشفتات','Shifts'],contract:['نهاية العقود','Contract end'],probation:['فترة التجربة','Probation'],document:['انتهاء الوثائق','Document expiry'],training:['التدريب','Training'],interview:['المقابلات','Interviews'],onboarding:['Onboarding','Onboarding'],offboarding:['Offboarding','Offboarding'],resignation:['الاستقالات','Resignations'],termination:['إنهاء العلاقة','Employment exits'],performance:['الأداء','Performance']};return hrL72(...(m[s]||[s,s]));}
function hr80SourceOptions(){return ['all','manual','leave','shift','contract','probation','document','training','interview','onboarding','offboarding','resignation','termination','performance'].map(s=>`<option value="${s}" ${hrCalendarSourceV80===s?'selected':''}>${escapeHtml(hr80SourceLabel(s))}</option>`).join('');}
function hr80DeptOptions(){return `<option value="">${hrL72('كل الإدارات','All departments')}</option>`+hrV72.departments.filter(d=>d.is_active!==false).map(d=>`<option value="${d.id}" ${hrCalendarDepartmentV80===String(d.id)?'selected':''}>${escapeHtml(hrDept72(d))}</option>`).join('');}
function hr80EmployeeOptions(){const rows=hrV72.employees.filter(e=>e.status!=='terminated'&&(!hrCalendarDepartmentV80||String(e.department_id||'')===String(hrCalendarDepartmentV80)));return `<option value="">${hrL72('كل الموظفين','All employees')}</option>`+rows.map(e=>`<option value="${e.id}" ${hrCalendarEmployeeV80===String(e.id)?'selected':''}>${escapeHtml(hrName72(e))}</option>`).join('');}
function hr80RangeLabel(){const r=hr80Range(),fmt=new Intl.DateTimeFormat(lang==='ar'?'ar-SA':'en-US',hrCalendarViewV80==='month'?{month:'long',year:'numeric'}:{day:'numeric',month:'short',year:'numeric'});if(hrCalendarViewV80==='month')return fmt.format(new Date(hrCalendarCursorV80.getFullYear(),hrCalendarCursorV80.getMonth(),1));return `${fmt.format(r.from)} — ${fmt.format(r.to)}`;}
function hr80DayName(d,short=false){return new Intl.DateTimeFormat(lang==='ar'?'ar-SA':'en-US',{weekday:short?'short':'long'}).format(d);}
function hr80EventTime(e){if(e.all_day||!e.start_at)return '';try{return new Intl.DateTimeFormat(lang==='ar'?'ar-SA':'en-US',{hour:'2-digit',minute:'2-digit'}).format(new Date(e.start_at));}catch(_){return ''}}
