async function fetchHrCalendarV80(force=false){
 if(!currentWorkspaceId)return;const key=hr80LoadedKey();if(hrCalendarLoadingV80)return;if(!force&&hrCalendarLoadedKeyV80===key&&!hrCalendarMissingV80)return;
 hrCalendarLoadingV80=true;hrCalendarMissingV80=false;if(activeNav==='hr'&&hrActiveTabV72==='calendar80')renderModule();
 try{const r=hr80Range(),src=hrCalendarSourceV80==='all'?null:[hrCalendarSourceV80];const params={p_workspace_id:currentWorkspaceId,p_from:hr80Ymd(r.from),p_to:hr80Ymd(r.to),p_employee_id:hrCalendarEmployeeV80||null,p_department_id:hrCalendarDepartmentV80||null,p_sources:src};
   const [cal,week]=await Promise.all([sb.rpc('tasky_hr_calendar_feed_v80',params),sb.rpc('tasky_hr_workforce_week_v80',{p_workspace_id:currentWorkspaceId,p_week_start:hr80Ymd(hr80StartWeek(hrCalendarCursorV80)),p_employee_id:hrCalendarEmployeeV80||null,p_department_id:hrCalendarDepartmentV80||null})]);
   if(cal.error)throw cal.error;if(week.error)throw week.error;hrCalendarEventsV80=Array.isArray(cal.data)?cal.data:[];hrWorkforceWeekV80=Array.isArray(week.data)?week.data:[];hrCalendarLoadedKeyV80=key;
 }catch(err){console.warn('HR V80',err);hrCalendarMissingV80=/does not exist|schema cache|calendar_feed_v80|workforce_week_v80/i.test(err?.message||'');if(!hrCalendarMissingV80)showTaskyDialog({title:'HR V80',message:err?.message||String(err),tone:'error'});
 }finally{hrCalendarLoadingV80=false;if(activeNav==='hr'&&hrActiveTabV72==='calendar80')renderModule();}}

function hr80QueueFetch(){if(!hrCalendarLoadingV80&&hrCalendarLoadedKeyV80!==hr80LoadedKey())setTimeout(()=>fetchHrCalendarV80(false),0);}
function hrCalendarTemplateV80(){hr80QueueFetch();if(hrCalendarMissingV80)return `<div class="hr80-shell"><div class="hr80-empty"><b>${hrL72('V80 غير مثبت','V80 is not installed')}</b><div style="margin-top:6px">${hrL72('شغّل Migration V80 بعد V79 ثم أعد المحاولة.','Run the V80 migration after V79, then retry.')}</div><button class="primary-btn" style="margin:12px auto 0" onclick="fetchHrCalendarV80(true)">${hrL72('إعادة المحاولة','Retry')}</button></div></div>`;
 const counts={leave:hrCalendarEventsV80.filter(e=>e.source_type==='leave').length,exp:hrCalendarEventsV80.filter(e=>['document','contract','probation'].includes(e.source_type)).length,int:hrCalendarEventsV80.filter(e=>e.source_type==='interview').length};
 return `<div class="hr80-shell"><div class="hr80-toolbar"><div><h3>${hrL72('تقويم الموارد البشرية وجدولة القوى العاملة','HR Calendar & Workforce Scheduling')}</h3><p>${hrL72('تقويم موحد للإجازات والشفتات والعقود والوثائق والتدريب والمقابلات ودورة حياة الموظف.','A unified calendar for leave, shifts, contracts, documents, training, interviews, and employee lifecycle milestones.')}</p></div><div class="hr80-actions"><div class="hr80-view-switch"><button class="${hrCalendarViewV80==='month'?'active':''}" onclick="hr80SetView('month')">${hrL72('شهر','Month')}</button><button class="${hrCalendarViewV80==='week'?'active':''}" onclick="hr80SetView('week')">${hrL72('أسبوع','Week')}</button><button class="${hrCalendarViewV80==='schedule'?'active':''}" onclick="hr80SetView('schedule')">${hrL72('جدولة','Schedule')}</button></div>${hrCanManage72()?`<button class="chip-btn" onclick="hr80OpenShiftForm()">${hrL72('تعيين شفت','Assign shift')}</button><button class="primary-btn" onclick="hr80OpenEventForm()"><svg><use href="#i-plus"/></svg>${hrL72('حدث HR','HR event')}</button>`:''}</div></div>
 <div class="hr80-filterbar"><div class="hr80-filters"><select onchange="hr80SetSource(this.value)">${hr80SourceOptions()}</select>${hrCanManage72()?`<select onchange="hr80SetDepartment(this.value)">${hr80DeptOptions()}</select><select onchange="hr80SetEmployee(this.value)">${hr80EmployeeOptions()}</select>`:''}</div><div class="hr80-nav"><button onclick="hr80Move(-1)">‹</button><button onclick="hr80Today()">${hrL72('اليوم','Today')}</button><div class="hr80-range-title">${escapeHtml(hr80RangeLabel())}</div><button onclick="hr80Move(1)">›</button><button onclick="fetchHrCalendarV80(true)">${hrL72('تحديث','Refresh')}</button></div></div>
 <div class="hr80-kpis"><div class="hr80-kpi"><span>${hrL72('المواعيد في النطاق','Events in range')}</span><b>${hrCalendarEventsV80.length}</b></div><div class="hr80-kpi"><span>${hrL72('الإجازات','Leave')}</span><b>${counts.leave}</b></div><div class="hr80-kpi warn"><span>${hrL72('عقود / وثائق / تجربة','Contract / document / probation')}</span><b>${counts.exp}</b></div><div class="hr80-kpi ${hr80ConflictCount()?'bad':''}"><span>${hrL72('تعارضات الجدولة','Schedule conflicts')}</span><b>${hr80ConflictCount()}</b></div></div>
 ${hrCalendarLoadingV80?`<div class="hr80-empty">${hrL72('جاري تحميل التقويم...','Loading calendar...')}</div>`:hrCalendarViewV80==='month'?hr80MonthHtml():hrCalendarViewV80==='week'?hr80WeekHtml():hr80ScheduleHtml()}
 <div class="hr80-note"><b>${hrL72('الخصوصية:','Privacy:')}</b> ${hrL72('التقويم يحترم صلاحيات HR. الوثائق لا تظهر للمدير المباشر افتراضيًا، والمقابلات تظهر لفريق التوظيف أو المحاور، والموظف يرى نطاقه المسموح فقط.','The calendar respects HR permissions. Documents are not shown to line managers by default, interviews are limited to recruiting staff or the assigned interviewer, and employees only see their permitted scope.')}</div></div>`;}

function hr80MonthHtml(){const first=new Date(hrCalendarCursorV80.getFullYear(),hrCalendarCursorV80.getMonth(),1),start=new Date(first);start.setDate(start.getDate()-start.getDay());const today=hr80Ymd(new Date()),heads=Array.from({length:7},(_,i)=>`<div>${escapeHtml(hr80DayName(hr80AddDays(start,i),true))}</div>`).join('');let cells='';for(let i=0;i<42;i++){const d=hr80AddDays(start,i),ev=hr80EventsOn(d),same=d.getMonth()===first.getMonth(),ymd=hr80Ymd(d);cells+=`<div class="hr80-day ${same?'':'muted'} ${ymd===today?'today':''}"><div class="hr80-day-num"><b>${d.getDate()}</b><span>${ev.length||''}</span></div><div class="hr80-event-list">${ev.slice(0,4).map(hr80EventButton).join('')}${ev.length>4?`<div class="hr80-more">+${ev.length-4} ${hrL72('أخرى','more')}</div>`:''}</div></div>`;}return `<div class="hr80-calendar"><div class="hr80-week-head">${heads}</div><div class="hr80-month-grid">${cells}</div></div>`;}
function hr80WeekHtml(){const r=hr80Range();return `<div class="hr80-week-grid">${Array.from({length:7},(_,i)=>{const d=hr80AddDays(r.from,i),ev=hr80EventsOn(d);return `<div class="hr80-week-col"><div class="hr80-week-col-head"><b>${escapeHtml(hr80DayName(d))}</b><span>${escapeHtml(new Intl.DateTimeFormat(lang==='ar'?'ar-SA':'en-US',{day:'numeric',month:'short'}).format(d))}</span></div><div class="hr80-week-body">${ev.map(hr80EventButton).join('')||`<div class="hr80-more">${hrL72('لا توجد مواعيد','No events')}</div>`}</div></div>`}).join('')}</div>`;}
function hr80EventButton(e){const emp=hr80EmpName(e),time=hr80EventTime(e),sub=[time,emp].filter(Boolean).join(' · ');return `<button class="hr80-event ${escapeHtml(e.source_type||'manual')}" onclick="hr80OpenEvent('${escapeHtml(e.event_id)}')"><b>${escapeHtml(hr80EventTitle(e))}</b>${sub?`<small>${escapeHtml(sub)}</small>`:''}</button>`;}

function hr80ScheduleHtml(){const start=hr80StartWeek(hrCalendarCursorV80),days=Array.from({length:7},(_,i)=>hr80AddDays(start,i)),groups=new Map();for(const r of hrWorkforceWeekV80){if(!groups.has(r.employee_id))groups.set(r.employee_id,{employee_id:r.employee_id,employee_no:r.employee_no,name_ar:r.full_name_ar,name_en:r.full_name_en,department_id:r.department_id,days:{}});groups.get(r.employee_id).days[r.schedule_date]=r;}if(!groups.size)return `<div class="hr80-empty">${hrL72('لا توجد بيانات موظفين في هذا النطاق.','No employee schedule data in this scope.')}</div>`;return `<div class="hr80-schedule-wrap"><table class="hr80-schedule"><thead><tr><th>${hrL72('الموظف','Employee')}</th>${days.map(d=>`<th>${escapeHtml(hr80DayName(d,true))}<br>${d.getDate()}/${d.getMonth()+1}</th>`).join('')}</tr></thead><tbody>${[...groups.values()].map(g=>`<tr><td><div class="hr80-person"><b>${escapeHtml(lang==='ar'?(g.name_ar||g.name_en):(g.name_en||g.name_ar)||'—')}</b><small>${escapeHtml(g.employee_no||'')}</small></div></td>${days.map(d=>hr80ScheduleCell(g,g.days[hr80Ymd(d)],d)).join('')}</tr>`).join('')}</tbody></table></div>`;}
function hr80ScheduleCell(g,r,d){if(!r)return `<td><button class="hr80-cell" onclick="hr80OpenShiftForm('${g.employee_id}','${hr80Ymd(d)}')">—</button></td>`;const shift=lang==='ar'?(r.shift_name_ar||r.shift_name_en):(r.shift_name_en||r.shift_name_ar),times=r.start_time&&r.end_time?`${String(r.start_time).slice(0,5)}–${String(r.end_time).slice(0,5)}`:'',tags=[];if(r.leave_status)tags.push(`<span class="hr80-mini leave">${hrL72('إجازة','Leave')} · ${escapeHtml(r.leave_status)}</span>`);if(r.attendance_status)tags.push(`<span class="hr80-mini att">${escapeHtml(r.attendance_status)}</span>`);if(r.conflict_code)tags.push(`<span class="hr80-mini conflict">${hrL72('تعارض','Conflict')}</span>`);return `<td><button class="hr80-cell ${r.is_work_day?'':'off'}" onclick="hr80OpenShiftForm('${g.employee_id}','${hr80Ymd(d)}')"><div class="hr80-shift">${escapeHtml(shift||hrL72('بدون شفت','No shift'))}</div><small>${escapeHtml(times)}${!r.is_work_day?` · ${hrL72('راحة','Off')}`:''}</small><div class="hr80-cell-tags">${tags.join('')}</div></button>${r.assignment_id&&hrCanManage72()?`<button class="hr80-remove-assignment" onclick="event.stopPropagation();hr80DeleteAssignment('${r.assignment_id}')">${hrL72('إزالة التعيين','Remove assignment')}</button>`:''}</td>`;}

