 hrAnalyticsStateV81.from=g('hr81From')||hr81YearStart();hrAnalyticsStateV81.to=g('hr81To')||hr81Today();hrAnalyticsStateV81.department_id=g('hr81Dept');hrAnalyticsStateV81.location=g('hr81Location');hrAnalyticsStateV81.key='';fetchHrAnalyticsV81(true);
