function hr82Status(s){const m={open:['مفتوح','Open','warn'],in_progress:['قيد الاعتماد','In approval','info'],approved:['معتمد','Approved','good'],rejected:['مرفوض','Rejected','bad'],completed:['مكتمل','Completed','good'],cancelled:['ملغي','Cancelled',''],draft:['مسودة','Draft',''],published:['منشورة','Published','good'],archived:['مؤرشفة','Archived','']};const x=m[s]||[s||'—',s||'—',''];return `<span class="hr82-chip ${x[2]}">${escapeHtml(hrL72(x[0],x[1]))}</span>`;}
