 if(!currentWorkspaceId||hr82State.loading)return;
 if(!force&&hr82State.key===currentWorkspaceId&&hr82State.data&&!hr82State.missing)return;
 hr82State.loading=true;hr82State.missing=false;if(activeNav==='hr'&&hrActiveTabV72==='selfservice82')renderModule();
