async function hr82SaveCalendar(ev,id){ev.preventDefault();const g=x=>document.getElementById(x)?.value||'',payload={id:id||null,name_ar:g('hr82CalAr'),name_en:g('hr82CalEn'),country_code:g('hr82CalCountry'),location:g('hr82CalLocation'),timezone:g('hr82CalTz'),is_default:!!document.getElementById('hr82CalDefault')?.checked,is_active:!!document.getElementById('hr82CalActive')?.checked};try{const {error}=await sb.rpc('tasky_hr_save_holiday_calendar_v82',{p_workspace_id:currentWorkspaceId,p_payload:payload});if(error)throw error;closeAddModal();await fetchHr82(true);}catch(err){showTaskyDialog({title:'HR V82',message:err?.message||String(err),tone:'error'});}}
function hr82OpenHolidayForm(id=''){const h=(hr82A().holidays||[]).find(x=>String(x.id)===String(id)),cals=hr82A().calendars||[];document.getElementById('addModalBody').innerHTML=`<div class="modal-head"><h3>${h?hrL72('تعديل عطلة','Edit holiday'):hrL72('إضافة عطلة','Add holiday')}</h3><button class="modal-close" onclick="closeAddModal()"><svg style="width:18px"><use href="#i-x"/></svg></button></div><form onsubmit="hr82SaveHoliday(event,'${h?.id||''}')"><div class="hr82-form-grid"><div class="field"><label>${hrL72('التقويم','Calendar')}</label><select id="hr82HolCal" required>${cals.map(c=>`<option value="${c.id}" ${String(c.id)===String(h?.calendar_id||cals.find(x=>x.is_default)?.id||'')?'selected':''}>${escapeHtml(lang==='ar'?(c.name_ar||c.name_en):(c.name_en||c.name_ar))}</option>`).join('')}</select></div><div class="field"><label>${hrL72('التاريخ','Date')}</label><input id="hr82HolDate" type="date" value="${escapeHtml(String(h?.holiday_date||'').slice(0,10))}" required></div><div class="field"><label>${hrL72('الاسم العربي','Arabic name')}</label><input id="hr82HolAr" value="${escapeHtml(h?.name_ar||'')}" required></div><div class="field"><label>English name</label><input id="hr82HolEn" value="${escapeHtml(h?.name_en||'')}"></div><div class="field"><label class="hr82-check"><input id="hr82HolPaid" type="checkbox" ${h?.paid===false?'':'checked'}>${hrL72('عطلة مدفوعة حسب سياسة المنشأة','Paid per company policy')}</label></div><div class="field full"><label>${hrL72('ملاحظات','Notes')}</label><textarea id="hr82HolNotes">${escapeHtml(h?.notes||'')}</textarea></div></div><button class="submit-btn" type="submit">${hrL72('حفظ العطلة','Save holiday')}</button></form>`;document.getElementById('addModalBody').classList.add('hr72-modal');document.getElementById('addModalOverlay').classList.remove('hidden');}
