function hr83Category(v){const m={medical:['تأمين طبي','Medical'],life:['تأمين حياة','Life'],dental:['أسنان','Dental'],vision:['نظر','Vision'],wellness:['رفاه وصحة','Wellness'],transport:['نقل','Transport'],meal:['وجبات','Meals'],phone:['اتصالات','Phone'],education:['تعليم','Education'],housing:['سكن','Housing'],other:['أخرى','Other']};return hrL72(...(m[v]||[v||'—',v||'—']));}
function hr83Status(v){const m={draft:['مسودة','Draft',''],published:['منشورة','Published','good'],closed:['مغلقة','Closed','warn'],archived:['مؤرشفة','Archived',''],requested:['بانتظار المراجعة','Requested','warn'],approved:['معتمدة','Approved','good'],active:['نشطة','Active','good'],waived:['تنازل','Waived',''],rejected:['مرفوضة','Rejected','bad'],ended:['منتهية','Ended',''],cancelled:['ملغاة','Cancelled','bad']};const x=m[v]||[v||'—',v||'—',''];return `<span class="hr83-chip ${x[2]}">${escapeHtml(hrL72(x[0],x[1]))}</span>`;}
