function hr83EligibleClient(p,e){if(!p||!e||p.status!=='published')return false;const today=new Date().toISOString().slice(0,10);if(p.enrollment_start&&today<String(p.enrollment_start).slice(0,10))return false;if(p.enrollment_end&&today>String(p.enrollment_end).slice(0,10))return false;const ets=p.eligible_employment_types||[],deps=p.eligible_department_ids||[],locs=p.eligible_locations||[];if(ets.length&&!ets.includes(e.employment_type))return false;if(deps.length&&!deps.map(String).includes(String(e.department_id||'')))return false;if(locs.length&&!locs.includes(e.work_location||''))return false;if(Number(p.minimum_tenure_months||0)>0&&e.hire_date){const h=new Date(e.hire_date),n=new Date(),months=(n.getFullYear()-h.getFullYear())*12+n.getMonth()-h.getMonth();if(months<Number(p.minimum_tenure_months||0))return false;}return true;}
