function hr83EnrollmentCard(e){const p=hr83Plan(e.plan_id),emp=hr83Emp(e.employee_id);return `<div class="hr83-row"><div class="hr83-row-main"><b>${escapeHtml(lang==='ar'?(p?.name_ar||p?.name_en):(p?.name_en||p?.name_ar)||'—')}</b><small>${escapeHtml(hr83Name(emp))}${p?.provider_name?` · ${escapeHtml(p.provider_name)}`:''}</small></div><div>${hr83Status(e.status)}</div><div class="hr83-row-money"><small>${hrL72('حصة الموظف','Employee')}</small><b>${hr83Money(hr83Monthly(e.employee_cost_override??p?.employee_cost,p?.cost_frequency),p?.currency||'SAR')}</b></div><div class="hr83-row-money"><small>${hrL72('حصة المنشأة','Employer')}</small><b>${hr83Money(hr83Monthly(e.employer_cost_override??p?.employer_cost,p?.cost_frequency),p?.currency||'SAR')}</b></div>${hr83CanManage()&&e.status==='requested'?`<div class="hr83-actions"><button class="platform-mini-btn primary" onclick="hr83ReviewEnrollment('${e.id}','approved')">${hrL72('اعتماد','Approve')}</button><button class="platform-mini-btn danger" onclick="hr83ReviewEnrollment('${e.id}','rejected')">${hrL72('رفض','Reject')}</button></div>`:'<div></div>'}</div>`;}
function hr83Plans(){if(!hr83CanManage())return hr83Overview();const d=hr83D();return `<section class="hr83-panel"><div class="hr83-panel-head"><div><h3>${hrL72('خطط المزايا','Benefit Plans')}</h3><p>${hrL72('التكلفة السنوية تحول داخليًا إلى مكافئ شهري عند تجهيز مسير الرواتب.','Annual cost is converted to a monthly equivalent for payroll preparation.')}</p></div><button class="primary-btn" onclick="hr83OpenPlan()">+ ${hrL72('خطة جديدة','New plan')}</button></div><div class="hr83-card-grid">${(d.plans||[]).map(p=>{const b=hr83Benefit(p.benefit_id);return `<article class="hr83-card"><div class="hr83-card-top"><div><span class="hr83-eyebrow">${escapeHtml(hr83Category(b?.category))}</span><h4>${escapeHtml(lang==='ar'?(p.name_ar||p.name_en):(p.name_en||p.name_ar))}</h4><p>${escapeHtml(p.provider_name||'—')} ${p.coverage_tier?`· ${escapeHtml(p.coverage_tier)}`:''}</p></div>${hr83Status(p.status)}</div><div class="hr83-costs"><div><span>${hrL72('الموظف','Employee')}</span><b>${hr83Money(hr83Monthly(p.employee_cost,p.cost_frequency),p.currency)}</b></div><div><span>${hrL72('المنشأة','Employer')}</span><b>${hr83Money(hr83Monthly(p.employer_cost,p.cost_frequency),p.currency)}</b></div></div><div class="hr83-card-foot"><small>${p.allow_dependents?`${hrL72('يسمح بالمعالين','Dependents allowed')} · ${Number(p.max_dependents||0)||'∞'}`:hrL72('فردي','Employee only')}</small><button class="platform-mini-btn" onclick="hr83OpenPlan('${p.id}')">${hrL72('تعديل','Edit')}</button></div></article>`}).join('')||`<div class="hr83-empty">${hrL72('أضف أول خطة مزايا.','Add your first benefit plan.')}</div>`}</div></section>`;}
function hr83Enrollments(){if(!hr83CanManage())return hr83Overview();const rows=hr83D().enrollments||[];return `<section class="hr83-panel"><div class="hr83-panel-head"><div><h3>${hrL72('طلبات واشتراكات المزايا','Benefit requests & enrollments')}</h3><p>${hrL72('طلبات الموظفين والمزايا المعتمدة والمنتهية.','Employee requests and approved/ended coverage.')}</p></div></div>${rows.map(hr83EnrollmentCard).join('')||`<div class="hr83-empty">${hrL72('لا توجد طلبات.','No requests.')}</div>`}</section>`;}
function hr83Dependents(){const d=hr83D(),rows=d.dependents||[];return `<section class="hr83-panel"><div class="hr83-panel-head"><div><h3>${hrL72('المعالون','Dependents')}</h3><p>${hr83CanManage()?hrL72('المعالون المسجلون للموظفين. البيانات محمية ضمن HR.','Dependents registered for employees. Data remains within HR permissions.'):hrL72('أضف أفراد الأسرة عند الحاجة لخطط تسمح بالتغطية العائلية.','Add family members when a benefit plan allows dependent coverage.')}</p></div><button class="primary-btn" onclick="hr83OpenDependent()">+ ${hrL72('إضافة معال','Add dependent')}</button></div><div class="hr83-card-grid">${rows.map(x=>`<article class="hr83-card"><div class="hr83-card-top"><div><h4>${escapeHtml(x.full_name)}</h4><p>${escapeHtml(hr83Relationship(x.relationship))}${hr83CanManage()?` · ${escapeHtml(hr83Name(hr83Emp(x.employee_id)))}`:''}</p></div>${x.active?hr83Status('active'):hr83Status('ended')}</div><div class="hr83-card-foot"><small>${x.date_of_birth?hr83Date(x.date_of_birth):'—'}${x.national_id_last4?` · ****${escapeHtml(x.national_id_last4)}`:''}</small><button class="platform-mini-btn" onclick="hr83OpenDependent('${x.id}')">${hrL72('تعديل','Edit')}</button></div></article>`).join('')||`<div class="hr83-empty">${hrL72('لا يوجد معالون مسجلون.','No dependents registered.')}</div>`}</div></section>`;}
function hr83Allowances(){if(!hr83CanManage()){const rows=(hr83D().allowances||[]).filter(x=>String(x.employee_id)===String(hr83D().employee_id||''));return `<section class="hr83-panel"><div class="hr83-panel-head"><div><h3>${hrL72('بدلاتي','My allowances')}</h3></div></div>${rows.map(hr83AllowanceRow).join('')||`<div class="hr83-empty">${hrL72('لا توجد بدلات مسجلة.','No allowances recorded.')}</div>`}</section>`;}const rows=hr83D().allowances||[];return `<section class="hr83-panel"><div class="hr83-panel-head"><div><h3>${hrL72('بدلات الموظفين','Employee allowances')}</h3><p>${hrL72('بدلات مستمرة أو مؤقتة. نوع البدل يحدد هل يظهر كإضافة أو استقطاع أو غير مرتبط بالمسير.','Recurring or temporary allowances. The allowance type determines earnings, deductions, or non-payroll treatment.')}</p></div><button class="primary-btn" onclick="hr83OpenAllowance()">+ ${hrL72('إسناد بدل','Assign allowance')}</button></div>${rows.map(hr83AllowanceRow).join('')||`<div class="hr83-empty">${hrL72('لا توجد بدلات مسندة.','No employee allowances assigned.')}</div>`}</section>`;}
function hr83AllowanceRow(a){const t=hr83AllowanceType(a.allowance_type_id),e=hr83Emp(a.employee_id);return `<div class="hr83-row"><div class="hr83-row-main"><b>${escapeHtml(lang==='ar'?(t?.name_ar||t?.name_en):(t?.name_en||t?.name_ar)||'—')}</b><small>${escapeHtml(hr83Name(e))} · ${escapeHtml((t?.payroll_treatment||'').replace('_',' '))}</small></div><div>${hr83Status(a.status)}</div><div class="hr83-row-money"><small>${a.frequency==='one_time'?hrL72('دفعة واحدة','One-time'):hrL72('شهري','Monthly')}</small><b>${hr83Money(a.amount,a.currency)}</b></div><div class="hr83-row-money"><small>${hrL72('من','From')}</small><b>${hr83Date(a.effective_from)}</b></div>${hr83CanManage()?`<div class="hr83-actions"><button class="platform-mini-btn" onclick="hr83OpenAllowance('${a.id}')">${hrL72('تعديل','Edit')}</button></div>`:'<div></div>'}</div>`;}
function hr83Setup(){if(!hr83CanManage())return hr83Overview();const d=hr83D();return `<div class="hr83-grid2"><section class="hr83-panel"><div class="hr83-panel-head"><div><h3>${hrL72('كتالوج المزايا','Benefits catalog')}</h3><p>${hrL72('أنواع المزايا العامة قبل إنشاء الخطط.','Benefit definitions used by plans.')}</p></div><button class="primary-btn" onclick="hr83OpenBenefit()">+ ${hrL72('ميزة','Benefit')}</button></div>${(d.catalog||[]).map(x=>`<div class="hr83-setup-row"><div><b>${escapeHtml(lang==='ar'?(x.name_ar||x.name_en):(x.name_en||x.name_ar))}</b><small>${escapeHtml(x.code)} · ${escapeHtml(hr83Category(x.category))}</small></div><button class="platform-mini-btn" onclick="hr83OpenBenefit('${x.id}')">${hrL72('تعديل','Edit')}</button></div>`).join('')||`<div class="hr83-empty">${hrL72('لا يوجد كتالوج بعد.','No catalog entries yet.')}</div>`}</section><section class="hr83-panel"><div class="hr83-panel-head"><div><h3>${hrL72('أنواع البدلات','Allowance types')}</h3><p>${hrL72('يحدد نوع البدل المعالجة في Payroll.','Allowance type controls payroll treatment.')}</p></div><button class="primary-btn" onclick="hr83OpenAllowanceType()">+ ${hrL72('نوع بدل','Allowance type')}</button></div>${(d.allowance_types||[]).map(x=>`<div class="hr83-setup-row"><div><b>${escapeHtml(lang==='ar'?(x.name_ar||x.name_en):(x.name_en||x.name_ar))}</b><small>${escapeHtml(x.code)} · ${escapeHtml(x.payroll_treatment)} · ${hr83Money(x.default_amount,x.currency)}</small></div><button class="platform-mini-btn" onclick="hr83OpenAllowanceType('${x.id}')">${hrL72('تعديل','Edit')}</button></div>`).join('')||`<div class="hr83-empty">${hrL72('لا توجد أنواع بدلات بعد.','No allowance types yet.')}</div>`}</section></div>`;}

function hr83Field(id,label,value='',type='text',extra=''){return `<div class="field"><label>${label}</label><input id="${id}" type="${type}" value="${escapeHtml(value??'')}" ${extra}></div>`;}
function hr83OpenBenefit(id=''){const x=id?hr83D().catalog.find(r=>String(r.id)===String(id)):null;document.getElementById('addModalBody').innerHTML=`<div class="modal-head"><h3>${x?hrL72('تعديل ميزة','Edit benefit'):hrL72('ميزة جديدة','New benefit')}</h3><button class="modal-close" onclick="closeAddModal()">×</button></div><form onsubmit="hr83SaveBenefit(event,'${x?.id||''}')"><div class="hr83-form-grid">${hr83Field('hr83BenCode',hrL72('الكود','Code'),x?.code||'','text','required')}${hr83Field('hr83BenAr',hrL72('الاسم العربي','Arabic name'),x?.name_ar||'','text','required')}${hr83Field('hr83BenEn','English name',x?.name_en||'')}<div class="field"><label>${hrL72('التصنيف','Category')}</label><select id="hr83BenCat">${['medical','life','dental','vision','wellness','transport','meal','phone','education','housing','other'].map(v=>`<option value="${v}" ${x?.category===v?'selected':''}>${hr83Category(v)}</option>`).join('')}</select></div><div class="field full"><label>${hrL72('الوصف','Description')}</label><textarea id="hr83BenDesc">${escapeHtml(x?.description_ar||'')}</textarea></div><div class="field"><label class="hr83-check"><input id="hr83BenActive" type="checkbox" ${x?.active===false?'':'checked'}>${hrL72('نشطة','Active')}</label></div></div><button class="submit-btn" type="submit">${hrL72('حفظ','Save')}</button></form>`;document.getElementById('addModalOverlay').classList.remove('hidden');}
async function hr83SaveBenefit(e,id){e.preventDefault();const g=x=>document.getElementById(x)?.value||'';try{const {error}=await sb.rpc('tasky_hr_save_benefit_catalog_v83',{p_workspace_id:currentWorkspaceId,p_payload:{id:id||null,code:g('hr83BenCode'),category:g('hr83BenCat'),benefit_kind:'insurance',name_ar:g('hr83BenAr'),name_en:g('hr83BenEn'),description_ar:g('hr83BenDesc'),active:!!document.getElementById('hr83BenActive')?.checked}});if(error)throw error;closeAddModal();await fetchHr83(true);}catch(err){showTaskyDialog({title:'HR V83',message:err?.message||String(err),tone:'error'});}}
function hr83OpenPlan(id=''){const x=id?hr83Plan(id):null,cats=hr83D().catalog||[];if(!cats.length){taskyToast(hrL72('أضف تعريف ميزة أولًا من تبويب الإعداد.','Add a benefit definition in Setup first.'),{tone:'warning'});return;}document.getElementById('addModalBody').innerHTML=`<div class="modal-head"><h3>${x?hrL72('تعديل خطة','Edit plan'):hrL72('خطة مزايا جديدة','New benefit plan')}</h3><button class="modal-close" onclick="closeAddModal()">×</button></div><form onsubmit="hr83SavePlan(event,'${x?.id||''}')"><div class="hr83-form-grid"><div class="field"><label>${hrL72('الميزة','Benefit')}</label><select id="hr83PlanBenefit">${cats.map(b=>`<option value="${b.id}" ${String(x?.benefit_id)===String(b.id)?'selected':''}>${escapeHtml(lang==='ar'?(b.name_ar||b.name_en):(b.name_en||b.name_ar))}</option>`).join('')}</select></div>${hr83Field('hr83PlanCode',hrL72('الكود','Code'),x?.code||'','text','required')}${hr83Field('hr83PlanAr',hrL72('الاسم العربي','Arabic name'),x?.name_ar||'','text','required')}${hr83Field('hr83PlanEn','English name',x?.name_en||'')}${hr83Field('hr83Provider',hrL72('المزود — اختياري','Provider — optional'),x?.provider_name||'')}${hr83Field('hr83Tier',hrL72('فئة التغطية','Coverage tier'),x?.coverage_tier||'')}${hr83Field('hr83EmpCost',hrL72('تكلفة الموظف','Employee cost'),x?.employee_cost||0,'number','min="0" step="0.01"')}${hr83Field('hr83ErCost',hrL72('تكلفة المنشأة','Employer cost'),x?.employer_cost||0,'number','min="0" step="0.01"')}<div class="field"><label>${hrL72('دورية التكلفة','Cost frequency')}</label><select id="hr83Freq"><option value="monthly" ${x?.cost_frequency!=='annual'?'selected':''}>${hrL72('شهري','Monthly')}</option><option value="annual" ${x?.cost_frequency==='annual'?'selected':''}>${hrL72('سنوي','Annual')}</option></select></div><div class="field"><label>${hrL72('الحالة','Status')}</label><select id="hr83PlanStatus">${['draft','published','closed','archived'].map(v=>`<option value="${v}" ${x?.status===v?'selected':''}>${v}</option>`).join('')}</select></div>${hr83Field('hr83EnrollStart',hrL72('بداية التسجيل','Enrollment start'),String(x?.enrollment_start||'').slice(0,10),'date')}${hr83Field('hr83EnrollEnd',hrL72('نهاية التسجيل','Enrollment end'),String(x?.enrollment_end||'').slice(0,10),'date')}${hr83Field('hr83CoverStart',hrL72('بداية التغطية','Coverage start'),String(x?.coverage_start||'').slice(0,10),'date')}${hr83Field('hr83CoverEnd',hrL72('نهاية التغطية','Coverage end'),String(x?.coverage_end||'').slice(0,10),'date')}${hr83Field('hr83Tenure',hrL72('حد الخدمة بالأشهر','Minimum tenure months'),x?.minimum_tenure_months||0,'number','min="0"')}<div class="field"><label class="hr83-check"><input id="hr83Deduct" type="checkbox" ${x?.employee_payroll_deduction?'checked':''}>${hrL72('استقطاع مساهمة الموظف عبر Payroll','Deduct employee contribution in payroll')}</label></div><div class="field"><label class="hr83-check"><input id="hr83Deps" type="checkbox" ${x?.allow_dependents?'checked':''}>${hrL72('يسمح بالمعالين','Allow dependents')}</label></div>${hr83Field('hr83MaxDeps',hrL72('الحد الأقصى للمعالين','Max dependents'),x?.max_dependents||0,'number','min="0" max="50"')}</div><button class="submit-btn" type="submit">${hrL72('حفظ الخطة','Save plan')}</button></form>`;document.getElementById('addModalOverlay').classList.remove('hidden');}
async function hr83SavePlan(e,id){e.preventDefault();const g=x=>document.getElementById(x)?.value||'';const payload={id:id||null,benefit_id:g('hr83PlanBenefit'),code:g('hr83PlanCode'),name_ar:g('hr83PlanAr'),name_en:g('hr83PlanEn'),provider_name:g('hr83Provider'),coverage_tier:g('hr83Tier'),currency:'SAR',employee_cost:g('hr83EmpCost'),employer_cost:g('hr83ErCost'),cost_frequency:g('hr83Freq'),employee_payroll_deduction:!!document.getElementById('hr83Deduct')?.checked,employer_cost_tracking:true,enrollment_start:g('hr83EnrollStart'),enrollment_end:g('hr83EnrollEnd'),coverage_start:g('hr83CoverStart'),coverage_end:g('hr83CoverEnd'),eligible_employment_types:[],eligible_department_ids:[],eligible_locations:[],minimum_tenure_months:g('hr83Tenure'),allow_dependents:!!document.getElementById('hr83Deps')?.checked,max_dependents:g('hr83MaxDeps'),status:g('hr83PlanStatus')};try{const {error}=await sb.rpc('tasky_hr_save_benefit_plan_v83',{p_workspace_id:currentWorkspaceId,p_payload:payload});if(error)throw error;closeAddModal();await fetchHr83(true);}catch(err){showTaskyDialog({title:'HR V83',message:err?.message||String(err),tone:'error'});}}
function hr83OpenDependent(id=''){const x=id?hr83D().dependents.find(r=>String(r.id)===String(id)):null,emps=hr83D().employees||[],empId=x?.employee_id||hr83D().employee_id||emps[0]?.id||'';document.getElementById('addModalBody').innerHTML=`<div class="modal-head"><h3>${x?hrL72('تعديل معال','Edit dependent'):hrL72('إضافة معال','Add dependent')}</h3><button class="modal-close" onclick="closeAddModal()">×</button></div><form onsubmit="hr83SaveDependent(event,'${x?.id||''}')"><div class="hr83-form-grid">${hr83CanManage()?`<div class="field"><label>${hrL72('الموظف','Employee')}</label><select id="hr83DepEmp">${emps.map(e=>`<option value="${e.id}" ${String(empId)===String(e.id)?'selected':''}>${escapeHtml(hr83Name(e))}</option>`).join('')}</select></div>`:`<input type="hidden" id="hr83DepEmp" value="${escapeHtml(empId)}">`}${hr83Field('hr83DepName',hrL72('الاسم الكامل','Full name'),x?.full_name||'','text','required')}<div class="field"><label>${hrL72('صلة القرابة','Relationship')}</label><select id="hr83DepRel">${['spouse','son','daughter','parent','other'].map(v=>`<option value="${v}" ${x?.relationship===v?'selected':''}>${hr83Relationship(v)}</option>`).join('')}</select></div>${hr83Field('hr83DepDob',hrL72('تاريخ الميلاد','Date of birth'),String(x?.date_of_birth||'').slice(0,10),'date')}${hr83Field('hr83DepId',hrL72('آخر 4 من الهوية — اختياري','ID last 4 — optional'),x?.national_id_last4||'','text','maxlength="4" pattern="[0-9]{4}"')}${hr83Field('hr83DepNat',hrL72('الجنسية','Nationality'),x?.nationality||'')}<div class="field"><label class="hr83-check"><input id="hr83DepActive" type="checkbox" ${x?.active===false?'':'checked'}>${hrL72('نشط','Active')}</label></div></div><button class="submit-btn" type="submit">${hrL72('حفظ','Save')}</button></form>`;document.getElementById('addModalOverlay').classList.remove('hidden');}
async function hr83SaveDependent(e,id){e.preventDefault();const g=x=>document.getElementById(x)?.value||'';try{const {error}=await sb.rpc('tasky_hr_save_dependent_v83',{p_workspace_id:currentWorkspaceId,p_payload:{id:id||null,employee_id:g('hr83DepEmp'),full_name:g('hr83DepName'),relationship:g('hr83DepRel'),date_of_birth:g('hr83DepDob'),national_id_last4:g('hr83DepId'),nationality:g('hr83DepNat'),active:!!document.getElementById('hr83DepActive')?.checked}});if(error)throw error;closeAddModal();await fetchHr83(true);}catch(err){showTaskyDialog({title:'HR V83',message:err?.message||String(err),tone:'error'});}}
function hr83OpenEnrollment(planId=''){const emp=hr83OwnEmp();if(!emp){taskyToast(hrL72('يجب ربط حسابك بسجل موظف أولًا.','Your account must be linked to an employee record first.'),{tone:'warning'});return;}const plans=(hr83D().plans||[]).filter(p=>hr83EligibleClient(p,emp)),deps=(hr83D().dependents||[]).filter(x=>String(x.employee_id)===String(emp.id)&&x.active);const selected=planId||plans[0]?.id||'';if(!plans.length){taskyToast(hrL72('لا توجد خطط مؤهلة مفتوحة للتسجيل حاليًا.','No eligible plans are currently open for enrollment.'),{tone:'warning'});return;}document.getElementById('addModalBody').innerHTML=`<div class="modal-head"><h3>${hrL72('طلب الاشتراك في ميزة','Request benefit enrollment')}</h3><button class="modal-close" onclick="closeAddModal()">×</button></div><form onsubmit="hr83SubmitEnrollment(event)"><div class="field"><label>${hrL72('الخطة','Plan')}</label><select id="hr83EnrollPlan">${plans.map(p=>`<option value="${p.id}" ${String(selected)===String(p.id)?'selected':''}>${escapeHtml(lang==='ar'?(p.name_ar||p.name_en):(p.name_en||p.name_ar))}</option>`).join('')}</select></div>${deps.length?`<div class="field"><label>${hrL72('المعالون المطلوب إضافتهم — إذا كانت الخطة تسمح','Dependents to include — if allowed')}</label><div class="hr83-check-list">${deps.map(d=>`<label><input type="checkbox" data-hr83-dep value="${d.id}"><span>${escapeHtml(d.full_name)} · ${escapeHtml(hr83Relationship(d.relationship))}</span></label>`).join('')}</div></div>`:''}<div class="hr83-note">${hrL72('تاسكي يعيد التحقق من الأهلية ونافذة التسجيل وعدد المعالين عند الإرسال.','Tasky re-checks eligibility, enrollment dates, and dependent limits on submission.')}</div><button class="submit-btn" type="submit">${hrL72('إرسال الطلب','Submit request')}</button></form>`;document.getElementById('addModalOverlay').classList.remove('hidden');}
async function hr83SubmitEnrollment(e){e.preventDefault();const deps=[...document.querySelectorAll('[data-hr83-dep]:checked')].map(x=>x.value);try{const {error}=await sb.rpc('tasky_hr_request_benefit_enrollment_v83',{p_workspace_id:currentWorkspaceId,p_plan_id:document.getElementById('hr83EnrollPlan').value,p_dependent_ids:deps});if(error)throw error;closeAddModal();await fetchHr83(true);taskyToast(hrL72('تم إرسال طلب الميزة','Benefit request submitted'),{tone:'success'});}catch(err){showTaskyDialog({title:'HR V83',message:err?.message||String(err),tone:'error'});}}
async function hr83ReviewEnrollment(id,status){const ok=await taskyConfirm(status==='approved'?hrL72('اعتماد الاشتراك؟','Approve enrollment?'):hrL72('رفض الطلب؟','Reject request?'),{title:'HR V83',tone:status==='approved'?'warning':'danger',confirmText:status==='approved'?hrL72('اعتماد','Approve'):hrL72('رفض','Reject')});if(!ok)return;try{const {error}=await sb.rpc('tasky_hr_review_benefit_enrollment_v83',{p_enrollment_id:id,p_status:status,p_note:null});if(error)throw error;await fetchHr83(true);}catch(err){showTaskyDialog({title:'HR V83',message:err?.message||String(err),tone:'error'});}}
function hr83OpenAllowanceType(id=''){const x=id?hr83AllowanceType(id):null;document.getElementById('addModalBody').innerHTML=`<div class="modal-head"><h3>${x?hrL72('تعديل نوع بدل','Edit allowance type'):hrL72('نوع بدل جديد','New allowance type')}</h3><button class="modal-close" onclick="closeAddModal()">×</button></div><form onsubmit="hr83SaveAllowanceType(event,'${x?.id||''}')"><div class="hr83-form-grid">${hr83Field('hr83ATCode',hrL72('الكود','Code'),x?.code||'','text','required')}${hr83Field('hr83ATAr',hrL72('الاسم العربي','Arabic name'),x?.name_ar||'','text','required')}${hr83Field('hr83ATEn','English name',x?.name_en||'')}${hr83Field('hr83ATAmount',hrL72('المبلغ الافتراضي','Default amount'),x?.default_amount||0,'number','min="0" step="0.01"')}<div class="field"><label>${hrL72('الدورية','Frequency')}</label><select id="hr83ATFreq"><option value="monthly" ${x?.frequency!=='one_time'?'selected':''}>${hrL72('شهري','Monthly')}</option><option value="one_time" ${x?.frequency==='one_time'?'selected':''}>${hrL72('مرة واحدة','One-time')}</option></select></div><div class="field"><label>${hrL72('المعالجة في المسير','Payroll treatment')}</label><select id="hr83ATTreat"><option value="earning" ${x?.payroll_treatment==='earning'?'selected':''}>${hrL72('إضافة','Earning')}</option><option value="deduction" ${x?.payroll_treatment==='deduction'?'selected':''}>${hrL72('استقطاع','Deduction')}</option><option value="non_payroll" ${x?.payroll_treatment==='non_payroll'?'selected':''}>${hrL72('خارج المسير','Non-payroll')}</option></select></div><div class="field"><label class="hr83-check"><input id="hr83ATActive" type="checkbox" ${x?.active===false?'':'checked'}>${hrL72('نشط','Active')}</label></div></div><button class="submit-btn" type="submit">${hrL72('حفظ','Save')}</button></form>`;document.getElementById('addModalOverlay').classList.remove('hidden');}
async function hr83SaveAllowanceType(e,id){e.preventDefault();const g=x=>document.getElementById(x)?.value||'';try{const {error}=await sb.rpc('tasky_hr_save_allowance_type_v83',{p_workspace_id:currentWorkspaceId,p_payload:{id:id||null,code:g('hr83ATCode'),name_ar:g('hr83ATAr'),name_en:g('hr83ATEn'),default_amount:g('hr83ATAmount'),currency:'SAR',frequency:g('hr83ATFreq'),payroll_treatment:g('hr83ATTreat'),active:!!document.getElementById('hr83ATActive')?.checked}});if(error)throw error;closeAddModal();await fetchHr83(true);}catch(err){showTaskyDialog({title:'HR V83',message:err?.message||String(err),tone:'error'});}}
function hr83OpenAllowance(id=''){const x=id?(hr83D().allowances||[]).find(r=>String(r.id)===String(id)):null,emps=hr83D().employees||[],types=(hr83D().allowance_types||[]).filter(t=>t.active||String(t.id)===String(x?.allowance_type_id));if(!types.length){taskyToast(hrL72('أضف نوع بدل أولًا من الإعداد.','Add an allowance type in Setup first.'),{tone:'warning'});return;}document.getElementById('addModalBody').innerHTML=`<div class="modal-head"><h3>${x?hrL72('تعديل بدل موظف','Edit employee allowance'):hrL72('إسناد بدل','Assign allowance')}</h3><button class="modal-close" onclick="closeAddModal()">×</button></div><form onsubmit="hr83SaveAllowance(event,'${x?.id||''}')"><div class="hr83-form-grid"><div class="field"><label>${hrL72('الموظف','Employee')}</label><select id="hr83AllowEmp">${emps.map(e=>`<option value="${e.id}" ${String(x?.employee_id)===String(e.id)?'selected':''}>${escapeHtml(hr83Name(e))}</option>`).join('')}</select></div><div class="field"><label>${hrL72('نوع البدل','Allowance type')}</label><select id="hr83AllowType">${types.map(t=>`<option value="${t.id}" ${String(x?.allowance_type_id)===String(t.id)?'selected':''}>${escapeHtml(lang==='ar'?(t.name_ar||t.name_en):(t.name_en||t.name_ar))}</option>`).join('')}</select></div>${hr83Field('hr83AllowAmount',hrL72('المبلغ','Amount'),x?.amount||types[0]?.default_amount||0,'number','min="0" step="0.01"')}<div class="field"><label>${hrL72('الدورية','Frequency')}</label><select id="hr83AllowFreq"><option value="monthly" ${x?.frequency!=='one_time'?'selected':''}>${hrL72('شهري','Monthly')}</option><option value="one_time" ${x?.frequency==='one_time'?'selected':''}>${hrL72('مرة واحدة','One-time')}</option></select></div>${hr83Field('hr83AllowFrom',hrL72('ساري من','Effective from'),String(x?.effective_from||new Date().toISOString().slice(0,10)).slice(0,10),'date','required')}${hr83Field('hr83AllowTo',hrL72('ساري إلى — اختياري','Effective to — optional'),String(x?.effective_to||'').slice(0,10),'date')}<div class="field"><label>${hrL72('الحالة','Status')}</label><select id="hr83AllowStatus">${['draft','active','ended','cancelled'].map(v=>`<option value="${v}" ${x?.status===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field full"><label>${hrL72('ملاحظة','Note')}</label><textarea id="hr83AllowNote">${escapeHtml(x?.note||'')}</textarea></div></div><button class="submit-btn" type="submit">${hrL72('حفظ','Save')}</button></form>`;document.getElementById('addModalOverlay').classList.remove('hidden');}
async function hr83SaveAllowance(e,id){e.preventDefault();const g=x=>document.getElementById(x)?.value||'';try{const {error}=await sb.rpc('tasky_hr_save_employee_allowance_v83',{p_workspace_id:currentWorkspaceId,p_payload:{id:id||null,employee_id:g('hr83AllowEmp'),allowance_type_id:g('hr83AllowType'),amount:g('hr83AllowAmount'),currency:'SAR',frequency:g('hr83AllowFreq'),effective_from:g('hr83AllowFrom'),effective_to:g('hr83AllowTo'),status:g('hr83AllowStatus'),note:g('hr83AllowNote')}});if(error)throw error;closeAddModal();await fetchHr83(true);}catch(err){showTaskyDialog({title:'HR V83',message:err?.message||String(err),tone:'error'});}}

// Make benefit snapshots visible in the existing payroll run table without altering historical data.
const hrOpenPayrollRunV75BaseV83=hrOpenPayrollRunV75;
hrOpenPayrollRunV75=function(id){hrOpenPayrollRunV75BaseV83(id);const r=hrPayrollRunV75(id),items=hrRunItemsV75(id);if(!r||!items.some(x=>Number(x.benefit_earnings||0)||Number(x.benefit_employee_deductions||0)||Number(x.benefit_employer_cost||0)))return;const modal=document.getElementById('addModalBody');if(!modal)return;const note=document.createElement('div');note.className='hr83-note';note.style.marginTop='10px';const earn=items.reduce((s,x)=>s+Number(x.benefit_earnings||0),0),ded=items.reduce((s,x)=>s+Number(x.benefit_employee_deductions||0),0),er=items.reduce((s,x)=>s+Number(x.benefit_employer_cost||0),0);note.innerHTML=`<b>${hrL72('لقطة V83 للمزايا والبدلات','V83 benefits & allowances snapshot')}</b><div class="hr83-payroll-mini"><span>${hrL72('إضافات','Earnings')}: <strong>${hr83Money(earn)}</strong></span><span>${hrL72('استقطاعات الموظفين','Employee deductions')}: <strong>${hr83Money(ded)}</strong></span><span>${hrL72('تكلفة مزايا على المنشأة','Employer benefit cost')}: <strong>${hr83Money(er)}</strong></span></div>`;modal.appendChild(note);};




/* ================= V84 HR EXPENSES, CLAIMS & REIMBURSEMENTS ================= */
let hr84State={loadedWorkspace:null,loading:false,missing:false,data:null,tab:'overview',openClaimId:null};
if(!HR_TABS_V72.some(x=>x[0]==='expenses84')){
  const ix=HR_TABS_V72.findIndex(x=>x[0]==='benefits83');
  HR_TABS_V72.splice(ix<0?HR_TABS_V72.length:ix+1,0,['expenses84','المصروفات والمطالبات','Expenses & Claims']);
}
const hrTabVisible72BaseV84=hrTabVisible72;
hrTabVisible72=function(id){if(id==='expenses84')return true;return hrTabVisible72BaseV84(id);};
const hrBodyV72BaseV84=hrBodyV72;
hrBodyV72=function(){if(hrActiveTabV72==='expenses84')return hr84Template();return hrBodyV72BaseV84();};
const setHrTabV72BaseV84=setHrTabV72;
setHrTabV72=function(id){setHrTabV72BaseV84(id);if(id==='expenses84')setTimeout(()=>fetchHr84(),0);};

function hr84D(){return hr84State.data||{policies:[],categories:[],claims:[],items:[],events:[],employees:[]};}
function hr84Self(){return hr84D().employee_id||null;}
function hr84CanFinance(){return !!hr84D().can_finance;}
function hr84CanPayroll(){return !!hr84D().can_payroll;}
function hr84CanSetup(){return !!(hr84D().can_manage||hr84D().can_payroll);}
function hr84OwnClaim(c){return String(c?.employee_id||'')===String(hr84Self()||'');}
function hr84HasManagerQueue(){return (hr84D().claims||[]).some(c=>!hr84OwnClaim(c)&&c.status==='manager_review');}
function hr84Emp(id){return (hr84D().employees||[]).find(x=>String(x.id)===String(id))||hrV72.employees?.find(x=>String(x.id)===String(id))||null;}
function hr84Name(e){return e?String(lang==='ar'?(e.full_name_ar||e.full_name_en):(e.full_name_en||e.full_name_ar)||'—'):'—';}
function hr84Policy(id){return (hr84D().policies||[]).find(x=>String(x.id)===String(id));}
function hr84Category(id){return (hr84D().categories||[]).find(x=>String(x.id)===String(id));}
function hr84Items(claimId){return (hr84D().items||[]).filter(x=>String(x.claim_id)===String(claimId));}
function hr84Events(claimId){return (hr84D().events||[]).filter(x=>String(x.claim_id)===String(claimId)).sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));}
function hr84Money(v,c='SAR'){try{return new Intl.NumberFormat(lang==='ar'?'ar-SA':'en-US',{style:'currency',currency:c||'SAR',maximumFractionDigits:2}).format(Number(v||0));}catch{return `${Number(v||0).toFixed(2)} ${c||'SAR'}`;}}
function hr84Date(v){return v?hrDate72(String(v).slice(0,10)):'—';}
function hr84DateTime(v){if(!v)return '—';try{return new Intl.DateTimeFormat(lang==='ar'?'ar-SA':'en-US',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v));}catch{return String(v);}}
function hr84Status(v){const m={draft:['مسودة','Draft',''],manager_review:['مراجعة المدير','Manager review','warn'],finance_review:['مراجعة HR/Payroll','HR/Payroll review','warn'],approved:['معتمدة','Approved','good'],rejected:['مرفوضة','Rejected','bad'],cancelled:['ملغاة','Cancelled','bad'],paid:['مدفوعة','Paid','good']};const x=m[v]||[v||'—',v||'—',''];return `<span class="hr84-chip ${x[2]}">${escapeHtml(hrL72(x[0],x[1]))}</span>`;}
function hr84Payment(v){const m={not_applicable:['غير محدد','Not set',''],pending:['بانتظار الدفع','Pending payment','warn'],scheduled:['مجدول بالمسير','Scheduled in payroll','info'],paid:['مدفوع','Paid','good'],cancelled:['ملغي','Cancelled','bad']};const x=m[v]||[v||'—',v||'—',''];return `<span class="hr84-chip ${x[2]}">${escapeHtml(hrL72(x[0],x[1]))}</span>`;}
function hr84CatType(v){const m={general:['عام','General'],travel:['سفر ومهمات','Travel'],mileage:['مسافة ومركبة','Mileage'],meal:['وجبات','Meals'],lodging:['سكن وفنادق','Lodging'],transport:['نقل','Transport'],communication:['اتصالات','Communication'],other:['أخرى','Other']};return hrL72(...(m[v]||[v||'—',v||'—']));}
function hr84EventName(v){const m={claim_created:['إنشاء المطالبة','Claim created'],item_saved:['حفظ بند','Item saved'],item_deleted:['حذف بند','Item deleted'],claim_submitted:['إرسال للموافقة','Claim submitted'],manager_approved:['اعتماد المدير','Manager approved'],manager_rejected:['رفض المدير','Manager rejected'],finance_approved:['اعتماد HR/Payroll','HR/Payroll approved'],finance_rejected:['رفض HR/Payroll','HR/Payroll rejected'],payment_recorded:['تسجيل الدفع','Payment recorded'],claim_cancelled:['إلغاء المطالبة','Claim cancelled']};return hrL72(...(m[v]||[v||'—',v||'—']));}
function hr84Field(id,label,value='',type='text',extra=''){return `<div class="field"><label>${label}</label><input id="${id}" type="${type}" value="${escapeHtml(String(value??''))}" ${extra}></div>`;}

async function fetchHr84(force=false){if(!currentWorkspaceId)return;if(hr84State.loading)return;if(!force&&hr84State.loadedWorkspace===currentWorkspaceId&&hr84State.data)return;hr84State.loading=true;hr84State.missing=false;if(activeNav==='hr'&&hrActiveTabV72==='expenses84')renderModule();try{const {data,error}=await sb.rpc('tasky_hr_expense_bootstrap_v84',{p_workspace_id:currentWorkspaceId});if(error)throw error;hr84State.data=data||{};hr84State.loadedWorkspace=currentWorkspaceId;}catch(err){console.warn('Tasky HR V84',err);hr84State.missing=/does not exist|schema cache|tasky_hr_expense/i.test(err?.message||'');if(!hr84State.missing)showTaskyDialog({title:'HR V84',message:err?.message||String(err),tone:'error'});}finally{hr84State.loading=false;if(activeNav==='hr'&&hrActiveTabV72==='expenses84')renderModule();}}
function hr84SetTab(t){hr84State.tab=t;renderModule();}
function hr84Tabs(){const tabs=[['overview','نظرة عامة','Overview'],['my','مطالباتي','My Claims']];if(hr84CanFinance()||hr84HasManagerQueue())tabs.push(['approvals','الموافقات والدفع','Approvals & Payment']);if(hr84CanSetup())tabs.push(['policies','السياسات والفئات','Policies & Categories']);return `<div class="hr84-tabs">${tabs.map(x=>`<button class="${hr84State.tab===x[0]?'active':''}" onclick="hr84SetTab('${x[0]}')">${escapeHtml(hrL72(x[1],x[2]))}</button>`).join('')}</div>`;}
function hr84Template(){if(hr84State.missing)return `<div class="hr84-shell"><div class="hr84-panel"><div class="hr84-warn">${hrL72('V84 غير مثبت بعد. شغّل Migration V84 في Supabase ثم أعد المحاولة.','V84 is not installed yet. Run the V84 migration in Supabase, then retry.')}</div><button class="primary-btn" style="margin-top:10px" onclick="fetchHr84(true)">${hrL72('إعادة المحاولة','Retry')}</button></div></div>`;if(hr84State.loading&&!hr84State.data)return `<div class="hr84-shell"><div class="hr84-loading">${hrL72('جارٍ تحميل المطالبات والمصروفات...','Loading expense claims…')}</div></div>`;if(!hr84State.data){setTimeout(()=>fetchHr84(),0);return `<div class="hr84-shell"><div class="hr84-loading">${hrL72('جارٍ تجهيز مركز المصروفات...','Preparing Expense Center…')}</div></div>`;}const body=hr84State.tab==='my'?hr84MyClaims():hr84State.tab==='approvals'?hr84Approvals():hr84State.tab==='policies'?hr84Policies():hr84Overview();return `<div class="hr84-shell"><div class="hr84-head"><div><h2>${hrL72('المصروفات والمطالبات','Expenses & Claims')}</h2><p>${hrL72('مطالبات موظفين بإيصالات، اعتماد المدير ثم HR/Payroll، تعويض خارجي أو عبر المسير، وحساب المسافة حسب سياسة المنشأة.','Employee claims with receipts, manager → HR/Payroll approval, external or payroll reimbursement, and company-defined mileage calculation.')}</p></div><div class="hr84-actions"><button class="primary-btn" onclick="hr84OpenNewClaim()">＋ ${hrL72('مطالبة جديدة','New claim')}</button><button class="chip-btn" onclick="fetchHr84(true)">↻ ${hrL72('تحديث','Refresh')}</button></div></div><div class="hr84-note"><b>${hrL72('حدود V84','V84 boundaries')}</b> · ${hrL72('حدود المصروفات ومعدل الكيلومتر وسياسات الإيصال تحددها المنشأة. التعويض عبر Payroll يزيد صافي المبلغ المدفوع ولا يغير Gross Salary أو أجر اشتراك GOSI تلقائيًا. لا يوجد تحويل بنكي مباشر في هذه النسخة.','Expense limits, mileage rates and receipt rules are company-configured. Payroll reimbursement increases net cash paid without changing Gross Salary or the GOSI contributory wage. V84 does not initiate bank transfers.')}</div>${hr84Tabs()}${body}</div>`;}

function hr84Overview(){const claims=hr84D().claims||[],own=claims.filter(hr84OwnClaim),scope=hr84CanFinance()?claims:own,pending=scope.filter(c=>['manager_review','finance_review'].includes(c.status)).length,approved=scope.filter(c=>c.status==='approved').reduce((s,c)=>s+Number(c.total_approved||0),0),paid=scope.filter(c=>c.status==='paid').reduce((s,c)=>s+Number(c.total_approved||0),0),exceptions=scope.filter(c=>c.has_policy_exception&& !['rejected','cancelled','paid'].includes(c.status)).length;const recent=scope.slice().sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at))).slice(0,6);return `<div class="hr84-grid"><div class="hr84-card"><small>${hrL72('مطالبات قيد المراجعة','Claims in review')}</small><strong>${pending}</strong></div><div class="hr84-card"><small>${hrL72('تعويض معتمد بانتظار الدفع','Approved awaiting payment')}</small><strong>${hr84Money(approved)}</strong></div><div class="hr84-card"><small>${hrL72('مدفوع ضمن النطاق','Paid in scope')}</small><strong>${hr84Money(paid)}</strong></div><div class="hr84-card"><small>${hrL72('استثناءات سياسة مفتوحة','Open policy exceptions')}</small><strong>${exceptions}</strong></div></div><div class="hr84-panel"><div class="hr84-toolbar"><h3>${hrL72('أحدث المطالبات','Recent claims')}</h3></div>${recent.length?hr84ClaimsTable(recent):`<div class="hr84-empty">${hrL72('لا توجد مطالبات بعد.','No claims yet.')}</div>`}</div>${hr84Self()?`<div class="hr84-panel"><h3>${hrL72('كيف تعمل المطالبة؟','How does a claim work?')}</h3><div class="hr84-kv"><div><small>1</small><b>${hrL72('أنشئ المطالبة وأضف البنود والإيصالات.','Create the claim and add items/receipts.')}</b></div><div><small>2</small><b>${hrL72('المدير يعتمدها ثم HR/Payroll يراجع المبلغ.','Manager approves, then HR/Payroll reviews the amount.')}</b></div><div><small>3</small><b>${hrL72('يتم التعويض خارج المسير أو ضمن Payroll حسب الاعتماد.','Reimburse externally or through payroll, as approved.')}</b></div></div></div>`:''}`;}
function hr84ClaimsTable(rows){return `<div class="hr84-table-wrap"><table class="hr84-table"><thead><tr><th>${hrL72('الرقم','No.')}</th><th>${hrL72('الموظف','Employee')}</th><th>${hrL72('المطالبة','Claim')}</th><th>${hrL72('المبلغ','Amount')}</th><th>${hrL72('الحالة','Status')}</th><th>${hrL72('الدفع','Payment')}</th><th></th></tr></thead><tbody>${rows.map(c=>`<tr><td><b>${escapeHtml(c.claim_no||'—')}</b><br><small>${hr84Date(c.created_at)}</small></td><td>${escapeHtml(hr84Name(hr84Emp(c.employee_id)))}</td><td>${escapeHtml(c.title||'—')}${c.has_policy_exception?`<div class="hr84-exception">⚠ ${hrL72('يوجد استثناء سياسة','Policy exception')}</div>`:''}</td><td class="hr84-money">${hr84Money(c.status==='draft'?c.total_claimed:(Number(c.total_approved||0)>0?c.total_approved:c.total_claimed),c.currency)}</td><td>${hr84Status(c.status)}</td><td>${hr84Payment(c.payment_status)}</td><td><button class="chip-btn" onclick="hr84OpenClaim('${c.id}')">${hrL72('فتح','Open')}</button></td></tr>`).join('')}</tbody></table></div>`;}
function hr84MyClaims(){const rows=(hr84D().claims||[]).filter(hr84OwnClaim).sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));return `<div class="hr84-panel"><div class="hr84-toolbar"><h3>${hrL72('مطالباتي','My Claims')}</h3><button class="primary-btn" onclick="hr84OpenNewClaim()">＋ ${hrL72('مطالبة جديدة','New claim')}</button></div>${rows.length?hr84ClaimsTable(rows):`<div class="hr84-empty">${hrL72('ابدأ بإنشاء أول مطالبة مصروف.','Create your first expense claim.')}</div>`}</div>`;}
function hr84Approvals(){const claims=hr84D().claims||[],mgr=claims.filter(c=>c.status==='manager_review'&&!hr84OwnClaim(c)&&(!!hr84D().can_manage||!hr84CanFinance())),fin=hr84CanFinance()?claims.filter(c=>c.status==='finance_review'):[],pay=hr84CanFinance()?claims.filter(c=>c.status==='approved'&&c.payment_status!=='paid'):[];return `<div class="hr84-panel"><h3>${hrL72('بانتظار المدير','Awaiting manager')}</h3>${mgr.length?hr84ClaimsTable(mgr):`<div class="hr84-empty">${hrL72('لا توجد موافقات مدير معلقة.','No manager approvals pending.')}</div>`}</div>${hr84CanFinance()?`<div class="hr84-panel"><h3>${hrL72('بانتظار HR / Payroll','Awaiting HR / Payroll')}</h3>${fin.length?hr84ClaimsTable(fin):`<div class="hr84-empty">${hrL72('لا توجد مطالبات للمراجعة المالية.','No claims awaiting finance review.')}</div>`}</div><div class="hr84-panel"><h3>${hrL72('معتمدة بانتظار الدفع','Approved awaiting payment')}</h3>${pay.length?hr84ClaimsTable(pay):`<div class="hr84-empty">${hrL72('لا توجد دفعات معلقة.','No payments pending.')}</div>`}</div>`:''}`;}
function hr84Policies(){const p=hr84D().policies||[],c=hr84D().categories||[];return `<div class="hr84-panel"><div class="hr84-toolbar"><h3>${hrL72('سياسات المصروفات','Expense Policies')}</h3><button class="primary-btn" onclick="hr84OpenPolicy()">＋ ${hrL72('سياسة','Policy')}</button></div>${p.length?`<div class="hr84-table-wrap"><table class="hr84-table"><thead><tr><th>${hrL72('السياسة','Policy')}</th><th>${hrL72('حد المطالبة','Claim limit')}</th><th>${hrL72('الإيصال من','Receipt from')}</th><th>${hrL72('معدل كم','Mileage rate')}</th><th>${hrL72('الموافقات','Approvals')}</th><th></th></tr></thead><tbody>${p.map(x=>`<tr><td><b>${escapeHtml(lang==='ar'?(x.name_ar||x.name_en):(x.name_en||x.name_ar))}</b><br><small>${escapeHtml(x.code)} ${x.is_default?'· '+hrL72('افتراضية','Default'):''}</small></td><td>${Number(x.max_claim_amount||0)>0?hr84Money(x.max_claim_amount,x.currency):hrL72('بدون حد','No limit')}</td><td>${Number(x.receipt_required_above||0)>0?hr84Money(x.receipt_required_above,x.currency):'—'}</td><td>${Number(x.mileage_rate||0)>0?`${Number(x.mileage_rate).toFixed(2)} ${x.currency}/${hrL72('كم','km')}`:'—'}</td><td>${x.manager_approval_required?hrL72('مدير','Manager'):'—'} → ${x.finance_approval_required?'HR/Payroll':'—'}</td><td><button class="chip-btn" onclick="hr84OpenPolicy('${x.id}')">${hrL72('تعديل','Edit')}</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="hr84-empty">${hrL72('لا توجد سياسة. يمكن العمل بدون سياسة، لكن معدل المسافة والحدود لن تكون معرفة.','No policy exists. Claims can still work, but mileage rate and policy limits will be undefined.')}</div>`}</div><div class="hr84-panel"><div class="hr84-toolbar"><h3>${hrL72('فئات المصروف','Expense Categories')}</h3><div class="hr84-actions"><button class="chip-btn" onclick="hr84ExportClaims()">⇩ CSV</button><button class="primary-btn" onclick="hr84OpenCategory()">＋ ${hrL72('فئة','Category')}</button></div></div><div class="hr84-table-wrap"><table class="hr84-table"><thead><tr><th>${hrL72('الكود','Code')}</th><th>${hrL72('الفئة','Category')}</th><th>${hrL72('النوع','Type')}</th><th>${hrL72('حد البند','Item limit')}</th><th>${hrL72('إيصال','Receipt')}</th><th></th></tr></thead><tbody>${c.map(x=>`<tr><td>${escapeHtml(x.code)}</td><td>${escapeHtml(lang==='ar'?(x.name_ar||x.name_en):(x.name_en||x.name_ar))}</td><td>${escapeHtml(hr84CatType(x.category_type))}</td><td>${Number(x.per_item_limit||0)>0?hr84Money(x.per_item_limit):'—'}</td><td>${x.receipt_required?'✓':'—'}</td><td><button class="chip-btn" onclick="hr84OpenCategory('${x.id}')">${hrL72('تعديل','Edit')}</button></td></tr>`).join('')}</tbody></table></div></div>`;}

function hr84OpenNewClaim(){if(!hr84Self()&&!hr84CanSetup()){taskyToast(hrL72('يجب ربط حسابك بسجل موظف قبل إنشاء مطالبة.','Your account must be linked to an employee record before creating a claim.'),{tone:'warning'});return;}const policies=(hr84D().policies||[]).filter(x=>x.active),emps=hr84D().employees||[],defaultPolicy=policies.find(x=>x.is_default)?.id||'';document.getElementById('addModalBody').innerHTML=`<div class="modal-head"><h3>${hrL72('مطالبة مصروف جديدة','New Expense Claim')}</h3><button class="modal-close" onclick="closeAddModal()">×</button></div><form onsubmit="hr84CreateClaim(event)"><div class="hr84-form-grid">${hr84CanSetup()?`<div class="field"><label>${hrL72('الموظف','Employee')}</label><select id="hr84ClaimEmp"><option value="">${hrL72('حسابي','My employee record')}</option>${emps.map(e=>`<option value="${e.id}">${escapeHtml(hr84Name(e))}</option>`).join('')}</select></div>`:''}<div class="field"><label>${hrL72('السياسة','Policy')}</label><select id="hr84ClaimPolicy"><option value="">${hrL72('بدون سياسة','No policy')}</option>${policies.map(p=>`<option value="${p.id}" ${String(p.id)===String(defaultPolicy)?'selected':''}>${escapeHtml(lang==='ar'?(p.name_ar||p.name_en):(p.name_en||p.name_ar))}</option>`).join('')}</select></div>${hr84Field('hr84ClaimTitle',hrL72('عنوان المطالبة','Claim title'),'','text','required')}${hr84Field('hr84TripFrom',hrL72('بداية المهمة/السفر — اختياري','Trip start — optional'),'','date')}${hr84Field('hr84TripTo',hrL72('نهاية المهمة/السفر — اختياري','Trip end — optional'),'','date')}<div class="field full"><label>${hrL72('الغرض','Purpose')}</label><textarea id="hr84ClaimPurpose"></textarea></div></div><button class="submit-btn" type="submit">${hrL72('إنشاء وإضافة البنود','Create & add items')}</button></form>`;document.getElementById('addModalOverlay').classList.remove('hidden');}
async function hr84CreateClaim(e){e.preventDefault();const g=x=>document.getElementById(x)?.value||'';try{const {data,error}=await sb.rpc('tasky_hr_create_expense_claim_v84',{p_workspace_id:currentWorkspaceId,p_payload:{employee_id:g('hr84ClaimEmp')||null,policy_id:g('hr84ClaimPolicy')||null,title:g('hr84ClaimTitle'),purpose:g('hr84ClaimPurpose'),trip_start:g('hr84TripFrom')||null,trip_end:g('hr84TripTo')||null,currency:'SAR'}});if(error)throw error;closeAddModal();await fetchHr84(true);hr84OpenClaim(data);setTimeout(()=>hr84OpenItem(data),80);}catch(err){showTaskyDialog({title:'HR V84',message:err?.message||String(err),tone:'error'});}}

function hr84OpenClaim(id){const c=(hr84D().claims||[]).find(x=>String(x.id)===String(id));if(!c)return;hr84State.openClaimId=id;const items=hr84Items(id),events=hr84Events(id),p=hr84Policy(c.policy_id),canEdit=c.status==='draft'&&(hr84OwnClaim(c)||hr84CanSetup()),canMgr=c.status==='manager_review'&&(!!hr84D().can_manage||(!hr84CanFinance()&&!hr84OwnClaim(c))),canFin=c.status==='finance_review'&&hr84CanFinance(),canPaid=c.status==='approved'&&c.payment_method==='external'&&hr84CanFinance();document.getElementById('addModalBody').innerHTML=`<div class="modal-head"><div><h3>${escapeHtml(c.claim_no)} · ${escapeHtml(c.title)}</h3><div class="hr84-actions">${hr84Status(c.status)} ${hr84Payment(c.payment_status)}</div></div><button class="modal-close" onclick="closeAddModal()">×</button></div><div class="hr84-kv"><div><small>${hrL72('الموظف','Employee')}</small><b>${escapeHtml(hr84Name(hr84Emp(c.employee_id)))}</b></div><div><small>${hrL72('المبلغ المطالب به','Claimed')}</small><b>${hr84Money(c.total_claimed,c.currency)}</b></div><div><small>${hrL72('المبلغ المعتمد','Approved')}</small><b>${hr84Money(c.total_approved,c.currency)}</b></div></div>${p?`<div class="hr84-note" style="margin-top:10px"><b>${escapeHtml(lang==='ar'?(p.name_ar||p.name_en):(p.name_en||p.name_ar))}</b>${c.has_policy_exception?` · ⚠ ${hrL72('تحتوي المطالبة استثناءً من السياسة','Claim contains a policy exception')}`:''}</div>`:''}<div class="hr84-toolbar" style="margin-top:14px"><h3>${hrL72('بنود المطالبة','Claim Items')}</h3>${canEdit?`<button class="primary-btn" onclick="hr84OpenItem('${c.id}')">＋ ${hrL72('إضافة بند','Add item')}</button>`:''}</div>${items.length?`<div class="hr84-table-wrap"><table class="hr84-table"><thead><tr><th>${hrL72('التاريخ','Date')}</th><th>${hrL72('الفئة والوصف','Category & description')}</th><th>${hrL72('المطلوب','Claimed')}</th><th>${hrL72('المعتمد','Approved')}</th><th>${hrL72('الإيصال','Receipt')}</th>${canEdit?'<th></th>':''}</tr></thead><tbody>${items.map(i=>{const cat=hr84Category(i.category_id);return `<tr><td>${hr84Date(i.expense_date)}</td><td><b>${escapeHtml(cat?(lang==='ar'?(cat.name_ar||cat.name_en):(cat.name_en||cat.name_ar)):'—')}</b><br>${escapeHtml(i.description||'')}${i.policy_exception?`<div class="hr84-exception">⚠ ${hrL72('استثناء سياسة','Policy exception')}</div>`:''}${i.distance_km?`<small>${Number(i.distance_km).toFixed(1)} km × ${Number(i.mileage_rate_snapshot||0).toFixed(2)}</small>`:''}</td><td>${hr84Money(i.claimed_amount,i.currency)}</td><td>${hr84Money(i.approved_amount,i.currency)}</td><td>${i.receipt_path?`<button class="chip-btn hr84-receipt" onclick="hr84OpenReceipt('${i.id}')">📎 ${hrL72('فتح','Open')}</button>`:(i.missing_receipt_reason?`<small>${escapeHtml(i.missing_receipt_reason)}</small>`:'—')}</td>${canEdit?`<td><button class="chip-btn" onclick="hr84DeleteItem('${i.id}')">🗑</button></td>`:''}</tr>`}).join('')}</tbody></table></div>`:`<div class="hr84-empty">${hrL72('لم تضف بنودًا بعد.','No items added yet.')}</div>`}<div class="hr84-toolbar" style="margin-top:14px"><h3>${hrL72('سجل الإجراء','Activity')}</h3></div><div class="hr84-timeline">${events.length?events.slice(0,12).map(ev=>`<div class="hr84-event"><b>${escapeHtml(hr84EventName(ev.event_type))}</b><br><small>${hr84DateTime(ev.created_at)}</small></div>`).join(''):`<div class="hr84-empty">—</div>`}</div><div class="hr84-actions" style="margin-top:16px">${canEdit&&items.length?`<button class="primary-btn" onclick="hr84SubmitClaim('${c.id}')">${hrL72('إرسال للموافقة','Submit for approval')}</button>`:''}${canEdit?`<button class="chip-btn" onclick="hr84CancelClaim('${c.id}')">${hrL72('إلغاء المطالبة','Cancel claim')}</button>`:''}${canMgr?`<button class="primary-btn" onclick="hr84OpenManagerDecision('${c.id}','approved')">${hrL72('اعتماد المدير','Manager approve')}</button><button class="danger-btn" onclick="hr84OpenManagerDecision('${c.id}','rejected')">${hrL72('رفض','Reject')}</button>`:''}${canFin?`<button class="primary-btn" onclick="hr84OpenFinanceApproval('${c.id}')">${hrL72('مراجعة واعتماد','Review & approve')}</button><button class="danger-btn" onclick="hr84OpenFinanceReject('${c.id}')">${hrL72('رفض','Reject')}</button>`:''}${canPaid?`<button class="primary-btn" onclick="hr84OpenPaid('${c.id}')">${hrL72('تسجيل كمدفوع','Mark paid')}</button>`:''}</div>${c.payment_method==='payroll'?`<div class="hr84-note" style="margin-top:10px">${hrL72('طريقة التعويض: ضمن مسير','Reimbursement method: Payroll')} · ${hr84Date(c.payroll_month)}${c.linked_payroll_run_id?' · '+hrL72('تم الربط بالمسير','Linked to payroll run'):''}</div>`:''}`;document.getElementById('addModalOverlay').classList.remove('hidden');}

function hr84OpenItem(claimId){const c=(hr84D().claims||[]).find(x=>String(x.id)===String(claimId));if(!c||c.status!=='draft')return;const cats=(hr84D().categories||[]).filter(x=>x.active),p=hr84Policy(c.policy_id);document.getElementById('addModalBody').innerHTML=`<div class="modal-head"><h3>${hrL72('إضافة بند مصروف','Add Expense Item')}</h3><button class="modal-close" onclick="hr84OpenClaim('${claimId}')">×</button></div><form onsubmit="hr84SaveItem(event,'${claimId}')"><div class="hr84-form-grid"><div class="field"><label>${hrL72('الفئة','Category')}</label><select id="hr84ItemCat" onchange="hr84ItemCatChanged()">${cats.map(x=>`<option value="${x.id}" data-kind="${x.category_type}">${escapeHtml(lang==='ar'?(x.name_ar||x.name_en):(x.name_en||x.name_ar))}</option>`).join('')}</select></div>${hr84Field('hr84ItemDate',hrL72('تاريخ المصروف','Expense date'),new Date().toISOString().slice(0,10),'date','required')}${hr84Field('hr84ItemMerchant',hrL72('التاجر/الجهة — اختياري','Merchant — optional'))}<div class="field" id="hr84AmountField"><label>${hrL72('المبلغ','Amount')}</label><input id="hr84ItemAmount" type="number" min="0.01" step="0.01" required></div><div class="field" id="hr84MileageField" style="display:none"><label>${hrL72('المسافة بالكيلومتر','Distance in km')}</label><input id="hr84Distance" type="number" min="0.01" step="0.01"><small>${p&&Number(p.mileage_rate||0)>0?`${hrL72('المعدل حسب السياسة','Policy rate')}: ${Number(p.mileage_rate).toFixed(2)} ${p.currency||'SAR'}/${hrL72('كم','km')}`:hrL72('يجب ضبط معدل الكيلومتر في السياسة.','Configure a mileage rate in the policy first.')}</small></div><div class="field full"><label>${hrL72('الوصف','Description')}</label><textarea id="hr84ItemDesc" required></textarea></div><div class="field full"><label>${hrL72('الإيصال — PDF/JPG/PNG/WebP حتى 10MB','Receipt — PDF/JPG/PNG/WebP up to 10MB')}</label><input id="hr84Receipt" type="file" accept="application/pdf,image/png,image/jpeg,image/webp"></div><div class="field full"><label>${hrL72('سبب عدم توفر الإيصال — عند الحاجة','Missing receipt reason — if needed')}</label><textarea id="hr84MissingReceipt"></textarea></div></div><div class="hr84-warn">${hrL72('إذا تجاوز البند حد الفئة أو مدة التقديم فسيُوسم كاستثناء سياسة لمراجعته، بدل تعديل المبلغ بصمت.','If an item exceeds a category limit or submission age, Tasky flags a policy exception for review instead of silently changing the amount.')}</div><button class="submit-btn" type="submit">${hrL72('حفظ البند','Save item')}</button></form>`;document.getElementById('addModalOverlay').classList.remove('hidden');setTimeout(hr84ItemCatChanged,0);}
function hr84ItemCatChanged(){const s=document.getElementById('hr84ItemCat'),kind=s?.selectedOptions?.[0]?.dataset?.kind,isMil=kind==='mileage';const m=document.getElementById('hr84MileageField'),a=document.getElementById('hr84AmountField'),ain=document.getElementById('hr84ItemAmount'),din=document.getElementById('hr84Distance');if(m)m.style.display=isMil?'block':'none';if(a)a.style.display=isMil?'none':'block';if(ain)ain.required=!isMil;if(din)din.required=isMil;}
async function hr84SaveItem(e,claimId){e.preventDefault();const c=(hr84D().claims||[]).find(x=>String(x.id)===String(claimId));if(!c)return;const g=x=>document.getElementById(x)?.value||'',file=document.getElementById('hr84Receipt')?.files?.[0]||null;let path=null;try{if(file){const allowed=['application/pdf','image/png','image/jpeg','image/webp'];if(file.size>10*1024*1024)throw new Error(hrL72('حجم الإيصال يتجاوز 10MB.','Receipt exceeds 10MB.'));if(file.type&&!allowed.includes(file.type))throw new Error(hrL72('صيغة الإيصال غير مدعومة.','Unsupported receipt type.'));const safe=(file.name||'receipt').replace(/[^a-zA-Z0-9._-]+/g,'_'),uid=crypto.randomUUID?crypto.randomUUID():`${Date.now()}_${Math.random().toString(36).slice(2)}`;path=`${currentWorkspaceId}/${c.employee_id}/${claimId}/${uid}_${safe}`;const up=await sb.storage.from('hr-expense-receipts').upload(path,file,{upsert:false,contentType:file.type||undefined});if(up.error)throw up.error;}const {error}=await sb.rpc('tasky_hr_save_expense_item_v84',{p_claim_id:claimId,p_payload:{category_id:g('hr84ItemCat'),expense_date:g('hr84ItemDate'),merchant:g('hr84ItemMerchant'),description:g('hr84ItemDesc'),claimed_amount:g('hr84ItemAmount')||0,distance_km:g('hr84Distance')||null,receipt_path:path,receipt_file_name:file?.name||null,receipt_mime_type:file?.type||null,receipt_file_size:file?.size||null,missing_receipt_reason:g('hr84MissingReceipt')}});if(error)throw error;await fetchHr84(true);hr84OpenClaim(claimId);}catch(err){if(path)await sb.storage.from('hr-expense-receipts').remove([path]).catch(()=>{});showTaskyDialog({title:'HR V84',message:err?.message||String(err),tone:'error'});}}
async function hr84OpenReceipt(itemId){const i=(hr84D().items||[]).find(x=>String(x.id)===String(itemId));if(!i?.receipt_path)return;const {data,error}=await sb.storage.from('hr-expense-receipts').createSignedUrl(i.receipt_path,120);if(error||!data?.signedUrl)return showTaskyDialog({title:'HR V84',message:error?.message||hrL72('تعذر فتح الإيصال.','Could not open receipt.'),tone:'error'});window.open(data.signedUrl,'_blank','noopener');}
async function hr84DeleteItem(itemId){const i=(hr84D().items||[]).find(x=>String(x.id)===String(itemId));if(!i)return;const ok=await taskyConfirm(hrL72('حذف بند المصروف؟','Delete this expense item?'),{title:'HR V84',tone:'danger',confirmText:hrL72('حذف','Delete')});if(!ok)return;try{const {data,error}=await sb.rpc('tasky_hr_delete_expense_item_v84',{p_item_id:itemId});if(error)throw error;if(data?.receipt_path)await sb.storage.from('hr-expense-receipts').remove([data.receipt_path]).catch(()=>{});await fetchHr84(true);hr84OpenClaim(i.claim_id);}catch(err){showTaskyDialog({title:'HR V84',message:err?.message||String(err),tone:'error'});}}
async function hr84SubmitClaim(id){const ok=await taskyConfirm(hrL72('إرسال المطالبة للموافقة؟ لن تستطيع تعديل البنود بعدها.','Submit this claim for approval? Items cannot be edited afterward.'),{title:'HR V84',tone:'warning',confirmText:hrL72('إرسال','Submit')});if(!ok)return;try{const {error}=await sb.rpc('tasky_hr_submit_expense_claim_v84',{p_claim_id:id});if(error)throw error;await fetchHr84(true);hr84OpenClaim(id);taskyToast(hrL72('تم إرسال المطالبة','Claim submitted'),{tone:'success'});}catch(err){showTaskyDialog({title:'HR V84',message:err?.message||String(err),tone:'error'});}}

function hr84OpenManagerDecision(id,decision){document.getElementById('addModalBody').innerHTML=`<div class="modal-head"><h3>${decision==='approved'?hrL72('اعتماد مطالبة الموظف','Approve employee claim'):hrL72('رفض مطالبة الموظف','Reject employee claim')}</h3><button class="modal-close" onclick="hr84OpenClaim('${id}')">×</button></div><form onsubmit="hr84ManagerDecision(event,'${id}','${decision}')"><div class="field"><label>${hrL72('ملاحظة','Note')}</label><textarea id="hr84DecisionNote" ${decision==='rejected'?'required':''}></textarea></div><button class="submit-btn" type="submit">${decision==='approved'?hrL72('اعتماد','Approve'):hrL72('رفض','Reject')}</button></form>`;}
async function hr84ManagerDecision(e,id,decision){e.preventDefault();try{const {error}=await sb.rpc('tasky_hr_manager_decide_expense_v84',{p_claim_id:id,p_decision:decision,p_note:document.getElementById('hr84DecisionNote')?.value||null});if(error)throw error;closeAddModal();await fetchHr84(true);taskyToast(decision==='approved'?hrL72('تم اعتماد المدير','Manager approval recorded'):hrL72('تم رفض المطالبة','Claim rejected'),{tone:decision==='approved'?'success':'warning'});}catch(err){showTaskyDialog({title:'HR V84',message:err?.message||String(err),tone:'error'});}}
