// V81 replaced the visibility function and unintentionally bypassed the earlier V79 tab guard.
// V85 makes the final visibility rules explicit instead of relying on override order.
function hrTabVisible72(id){
  if(id==='permissions')return currentUserRole==='admin';
  if(id==='launch85'||id==='automation79'||id==='cases'||id==='workforce'||id==='analytics'||id==='offboarding')return hrCanManage72();
  if(id==='recruitment')return hrCanRecruit72();
  if(id==='compensation'||id==='calendar80'||id==='selfservice82'||id==='benefits83'||id==='expenses84')return true;
  return true;
}
