// Preserve the horizontal HR tab position across every HR render, including async lazy refreshes.
// This fixes the bar jumping back to the first tab after opening a later HR section.
let hr85TabBarScroll={workspace:null,left:0};
function hr85CaptureTabBar(){
  if(activeNav!=='hr'||!currentWorkspaceId)return;
  const tabs=document.querySelector('.hr72-tabs');
  if(!tabs)return;
  hr85TabBarScroll={workspace:currentWorkspaceId,left:Number(tabs.scrollLeft||0)};
}
function hr85RestoreTabBar(){
  if(activeNav!=='hr'||!currentWorkspaceId)return;
  const tabs=document.querySelector('.hr72-tabs');
  if(!tabs)return;
  if(hr85TabBarScroll.workspace===currentWorkspaceId)tabs.scrollLeft=Number(hr85TabBarScroll.left||0);
  const active=tabs.querySelector('.hr72-tab.active');
  if(active&&typeof active.scrollIntoView==='function'){
    const tr=tabs.getBoundingClientRect(),ar=active.getBoundingClientRect();
    if(ar.left<tr.left+6||ar.right>tr.right-6)active.scrollIntoView({behavior:'auto',block:'nearest',inline:'nearest'});
  }
  hr85TabBarScroll={workspace:currentWorkspaceId,left:Number(tabs.scrollLeft||0)};
}
document.addEventListener('scroll',e=>{
  const el=e.target;
  if(activeNav==='hr'&&el?.classList?.contains('hr72-tabs')&&currentWorkspaceId){
    hr85TabBarScroll={workspace:currentWorkspaceId,left:Number(el.scrollLeft||0)};
  }
},true);
const renderModuleBaseV85=renderModule;
renderModule=function(...args){
  if(activeNav==='hr')hr85CaptureTabBar();
  const result=renderModuleBaseV85.apply(this,args);
  if(activeNav==='hr')requestAnimationFrame(()=>requestAnimationFrame(hr85RestoreTabBar));
  return result;
};

